NAME = 'CzeCSP: Czech Český studijní překlad'
BOOK = 'Judges'

CHAPTERS = {
    1: {
        1: 'I stalo se po smrti Jozua, že se synové Izraele doptávali Hospodina: Kdo z nás vytáhne proti Kenaancům ⌈jako první,⌉ aby s nimi vedl válku?',
        2: 'A Hospodin odpověděl: Vytáhne Juda. Hle, vydal jsem tu zemi do jeho ruky.',
        3: 'Juda řekl svému bratru Šimeónovi: Vytáhni se mnou do území mého losu a bojujme proti Kenaancům. A já s tebou také půjdu do území tvého losu. Šimeón šel tedy s ním.',
        4: 'Juda vytáhl a Hospodin vydal Kenaance a Perizejce do jejich rukou. Pobili je v Bezeku, deset tisíc mužů.',
        5: 'Přitom nalezli v Bezeku Adoní–bezeka, bojovali proti němu a pobili Kenaance a Perizejce.',
        6: 'Adoní–bezek však utekl a oni jej pronásledovali. Chytili ho a usekli mu palce na rukou i na nohou.',
        7: 'Adoní–bezek nato řekl: Sedmdesát králů s useknutými palci na rukou a na nohou sbírávalo pod mým stolem. Jak jsem jednal já, tak mi Bůh odplatil. Přivedli ho do Jeruzaléma a tam zemřel.',
        8: 'Synové Judovi bojovali proti Jeruzalému, dobyli jej, vybili ho ostřím meče a město podpálili.',
        9: 'Potom synové Judovi sestoupili do boje s Kenaanci sídlícími na pohoří, v Negebu a v Šefele.',
        10: 'Tak táhl Juda proti Kenaancům, sídlícím v Chebrónu (jméno Chebrónu bylo předtím Kirjat–arba) a pobili Šéšaje, Achímana a Talmaje.',
        11: 'Odtud táhl proti obyvatelům Debíru (jméno Debíru bylo předtím Kirjat–sefer).',
        12: 'Tehdy řekl Káleb: Kdo přepadne Kirjat–sefer a dobude ho, tomu dám svou dceru Aksu, za ženu.',
        13: 'Dobyl ho Otníel, syn ⌈Kenazův, mladší bratr Káleba,⌉ a on mu dal svou dceru Aksu za ženu.',
        14: 'I stalo se, když přišla, že jej navedla, aby žádal od jejího otce pole. Sesedla z osla a Káleb se jí zeptal: ⌈Jaké máš⌉ přání?',
        15: 'Odpověděla mu: Dej mi požehnání, protože ⌈jsi mě provdal do jižní země,⌉ dej mi vodní nádrže. Káleb jí tedy dal horní i dolní nádrže.',
        16: 'Synové Kénijce, Mojžíšova tchána, vytáhli z Ír–hatmarímu se syny Judovými do judské pustiny, která je ⌈na jih od Aradu,⌉ putovali a usadili se s tím lidem.',
        17: 'A Juda šel se svým bratrem Šimeónem, pobili Kenaance sídlící v Sefatu a zasvětili je zkáze. Potom nazvali to město jménem Chorma.',
        18: 'Juda také dobyl Gazu a její území, Aškalón a jeho území a Ekrón a jeho území.',
        19: 'Hospodin byl s Judou a ten si podrobil pohoří. Ale ne byl schopen podrobit si obyvatele údolí, protože měli železné vozy.',
        20: 'Kálebovi dali Chebrón, jak to Mojžíš vyhlásil, a on odtamtud vyhnal tři syny Anákovy.',
        21: 'Avšak Jebúsejce, obyvatele Jeruzaléma, si synové Benjamínovi nepodrobili a Jebúsejci pobývali se syny Benjamínovými v Jeruzalémě až do tohoto dne.',
        22: 'Také dům Josefův vystoupil k Bét–elu a Hospodin byl s nimi.',
        23: 'Dům Josefův pak ⌈provedl v Bét–elu průzkum;⌉ jméno toho města bylo předtím Lúz.',
        24: 'Průzkumníci viděli muže vycházejícího z města a řekli mu: Ukaž nám teď průchod do města a my ti prokážeme milosrdenství.',
        25: 'Ukázal jim tedy průchod do města. Oni to město vybili ostřím meče, ale toho muže a celou jeho rodinu propustili.',
        26: 'A ten muž šel do chetejské země, vystavěl město a nazval je jménem Lúz. To je jeho jméno až do tohoto dne.',
        27: 'Manases si však nepodrobil Bét–šeán a jeho vesnice, Taanak a jeho vesnice, obyvatele Dóru a jeho vesnic, obyvatele Jibleámu a jeho vesnic a obyvatele Megida a jeho vesnic. Kenaanci si tedy umínili v této zemi zůstat.',
        28: 'I stalo se, když se Izrael vzmohl, že uložil Kenaancům nucené práce, ale úplně si je nepodrobil.',
        29: 'Ani Efrajim si nepodrobil Kenaance, sídlící v Gezeru a Kenaanci pobývali uprostřed něj v Gezeru.',
        30: 'Zabulón si nepodrobil obyvatele Kitrónu a obyvatele Nahalólu. Kenaanci pobývali uprostřed nich a byli vydáni na nucené práce.',
        31: 'Ašer si nepodrobil obyvatele Aka, obyvatele Sidónu, Achlábu, Akzíbu, Chelby, Afíku a Rechóbu.',
        32: 'Ášerovci tak sídlili uprostřed Kenaanců usazených v zemi, protože si je nepodrobili.',
        33: 'Neftalí si nepodrobil obyvatele Bét–šemeše a obyvatele Bét–anatu a pobýval mezi Kenaanci usazenými v té zemi. Obyvatelé Bét–šemeše a Bét–anatu jim byli vydáni na nucené práce.',
        34: 'Emorejci zatlačili syny Danovy do pohoří, neboť jim nedovolili sestupovat do údolí.',
        35: 'Emorejci si tedy umínili zůstat v Har–cheresu, v Ajalónu a v Šaalbímu. Těžce na ně dolehla ruka domu Josefova a byli vydáni na nucené práce.',
        36: 'Emorejská hranice vedla od ⌈průsmyku Akrabim,⌉ od Sély až nahoru.',
    },
    2: {
        1: 'Hospodinův anděl pak vystoupil z Gilgálu do Bokímu a řekl: Vyvedl jsem vás z Egypta a přivedl jsem vás do země, o které jsem přísahal vašim otcům a řekl jsem: Navěky nezruším svou smlouvu s vámi.',
        2: 'Vy naopak neuzavřete smlouvu s obyvateli této země. Jejich oltáře strhnete. Ale neuposlechli jste mě. Co jste to provedli?',
        3: '⌈Však jsem také řekl:⌉ Nevyženu je před vámi. Budou vám ostnem v boku a jejich bohové budou pro vás léčkou.',
        4: 'I stalo se, když Hospodinův anděl mluvil tato slova ke všem synům Izraele, že lid pozvedl hlas a rozplakal se.',
        5: 'A nazvali ono místo jménem Bokím a obětovali tam Hospodinu.',
        6: 'Když Jozue propustil lid, synové Izraele odešli každý do svého dědictví, aby ⌈tu zemi obsadili.⌉',
        7: 'Lid sloužil Hospodinu po všechny Jozuovy dny a všechny dny starších, kteří ⌈Jozua přežili⌉ a kteří spatřili celé to velké Hospodinovo dílo, jež vykonal pro Izrael.',
        8: 'Jozue, syn Núnův, otrok Hospodinův, zemřel ve věku sto deseti let.',
        9: 'Pohřbili ho na území jeho dědictví v Timnat–cheresu, v efrajimském pohoří severně od hory Gaaš.',
        10: 'A také celá ona generace byla připojena ke svým otcům. Po nich potom povstala jiná generace, která neznala Hospodina ani dílo, jež pro Izrael vykonal.',
        11: 'Synové Izraele páchali to, co je ⌈zlé v Hospodinových očích,⌉ a sloužili baalům.',
        12: 'Opustili Hospodina, Boha svých otců, který je vyvedl z egyptské země, a chodili za jinými bohy z bohů těch národů, které byly okolo nich, ⌈klaněli se jim⌉ a provokovali Hospodina ke hněvu.',
        13: 'Opustili Hospodina a sloužili Baalovi a Aštoretě.',
        14: 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on je vydal do ruky pustošitelů, kteří je plenili. Vydal je do ruky jejich okolním nepřátelům a nemohli už před svými nepřáteli obstát.',
        15: 'Všude, kam vytáhli, byla ⌈Hospodinova ruka proti nim⌉ ke zlému, jak to Hospodin prohlásil a jak jim to Hospodin odpřisáhl. Bylo jim velmi úzko.',
        16: 'Hospodin tedy dával povstat soudcům a ti je zachraňovali z ruky jejich pustošitelů.',
        17: 'Ale ani své soudce neposlouchali, protože chodili smilnit za jinými bohy a klaněli se jim. Odvrátili se rychle od té cesty, po níž chodili jejich otcové v poslušnosti Hospodinových příkazů. Oni tak nejednali.',
        18: 'A když Hospodin dával kvůli nim povstat soudcům, ⌈byl Hospodin s tím⌉ soudcem a zachraňoval je z ruky jejich nepřátel po všechny dny toho soudce, neboť Hospodin se slitovával kvůli jejich sténání před jejich utiskovateli a poháněči.',
        19: 'Když však soudce zemřel, stalo se, že se navrátili zpět a ⌈vrhali se do zkázy⌉ více než jejich otcové, chodili za jinými bohy, sloužili jim a klaněli se jim. Nevzdali se svých činů ani svých zatvrzelých cest.',
        20: 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on řekl: Kvůli tomu, že tento národ přestoupil mou smlouvu, kterou jsem dal jejich otcům, a neposlechli mě,',
        21: 'ani já je už nenechám podrobit si nikoho z národů, které Jozue zanechal, než zemřel.',
        22: 'To abych jejich prostřednictvím Izrael zkoušel, zda budou zachovávat Hospodinovu cestu, aby po ní chodili, jak to zachovávali jejich otcové, nebo ne.',
        23: 'Tak Hospodin ponechal tyto národy, aniž by si je rychle podrobili, ani je ne vydal do Jozuovy ruky.',
    },
    3: {
        1: 'A toto jsou národy, které Hospodin ponechal, aby jejich prostřednictvím zkoušel Izrael, všechny, kteří nepoznali žádné boje o Kenaan,',
        2: 'aby generace synů Izraele poznaly aspoň pro své poučení, co je válka, aspoň ti, kteří ji předtím nepoznali:',
        3: 'Pět pelištejských vladařů a všechny Kenaance, Sidónce a Chivejce sídlící na libanonském pohoří od hory Baal–chermón až k Lebo–Chamátu.',
        4: 'Zůstali, aby byl skrze ně Izrael zkoušen, aby se poznalo, budou–li poslouchat Hospodinovy příkazy, které dal jejich otcům ⌈prostřednictvím Mojžíše.⌉',
        5: 'A synové Izraele bydleli uprostřed ⌈Kenaanců, Chetejců a Emorejců, Perizejců, Chivejců a Jebúsejců.⌉',
        6: 'Brali si jejich dcery za ženy a své dcery dávali jejich synům a sloužili jejich bohům.',
        7: 'Synové Izraele páchali to, co je zlé v Hospodinových očích, zapomínali na Hospodina, svého Boha, a sloužili baalům a ašerám.',
        8: 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on je vydal do ruky Kúšana Rišátajimského, krále Aramského Dvojříčí. Synové Izraele sloužili Kúšanovi Rišátajimskému osm let.',
        9: 'Synové Izraele volali k Hospodinu o pomoc a Hospodin dal pro syny Izraele povstat zachránci. Zachránil je Otníel, syn ⌈Kenazův, mladší bratr Káleba.⌉',
        10: 'Spočinul na něm Duch Hospodinův a on Izrael soudil. Vytáhl do boje a Hospodin vydal do jeho ruky aramejského krále Kúšana Rišátajimského. Jeho ruka na Kúšana Rišátajimského mocně dolehla.',
        11: 'A země měla čtyřicet let klid. Otníel, syn Kenazův, pak zemřel.',
        12: 'Avšak synové Izraele dále páchali to, co je zlé v Hospodinových očích, a Hospodin posilnil moábského krále Eglóna proti Izraeli kvůli tomu, že páchali to, co je v Hospodinových očích zlé.',
        13: 'Ten k sobě shromáždil syny Amónovy a Amálekovy. Vytáhl, přepadl Izrael a obsadili Ír–hatmarím.',
        14: 'Synové Izraele pak sloužili moábskému králi Eglónovi osmnáct let.',
        15: 'Synové Izraele tedy volali k Hospodinu o pomoc a Hospodin dal pro ně povstat zachránci Ehúdovi, synu Géry, ⌈syna Ben jamínova,⌉ muži ⌈nevládnoucímu pravou rukou.⌉ Jeho prostřednictvím poslali synové Izraele moábskému králi Eglónovi dar.',
        16: 'Ehúd si zhotovil dvojsečný meč gomer dlouhý a připásal si ho pod šaty na pravý bok.',
        17: 'I přinesl moábskému králi Eglónovi dar. Eglón byl hrozně tlustý muž.',
        18: 'A stalo se, když předal dar, že Ehúd propustil lid, který ten dar nesl.',
        19: 'Sám se vrátil od tesaných obrazů u Gilgálu a řekl: Mám pro tebe tajné poselství, králi. On řekl: Tiše! Všichni, kdo stáli kolem něho, od něj odešli.',
        20: 'Ehúd před něj předstoupil, když seděl v chladné horní místnosti, kterou měl pouze pro sebe. Ehúd řekl: Mám pro tebe Boží slovo. On nato povstal z křesla.',
        21: 'A Ehúd vztáhl svou levou ruku, vzal ten meč od pravého boku a vrazil mu ho do břicha.',
        22: 'Za čepelí pronikl také jílec a tuk se za čepelí zavřel, protože nevytáhl meč z břicha. Vyšel zadem.',
        23: 'Ehúd pak vyšel na chodbu, zavřel za sebou dveře horní místnosti a zamkl.',
        24: 'Jakmile odešel, vstoupili jeho otroci, podívali se a hle, dveře horní místnosti byly zamčeny. Řekli si: On jistě ⌈koná potřebu⌉ v chladném pokoji.',
        25: 'Přešlapovali tam až hanba, avšak hle, nikdo dveře horní místnosti neotvírá. Vzali klíč, otevřeli a hle, jejich pán leží na zemi mrtvý.',
        26: 'Ehúd unikl. Zatímco otáleli, on prošel kolem tesaných obrazů a unikl do Seíry.',
        27: 'I stalo se, když přišel, že zatroubil na beraní roh na efrajimském pohoří, synové Izraele s ním sestoupili z pohoří a on byl v jejich čele.',
        28: 'Řekl jim: Pospěšte za mnou, protože Hospodin vám vydal do ruky vaše moábské nepřátele. Sestoupili za ním a dobyli jordánské brody na Moábovi. A nedovolili nikomu projít.',
        29: 'V onen čas pobili z Moábu okolo deseti tisíc mužů, samé urostlé a zdatné muže. Nikdo neunikl.',
        30: 'V onen den byl Moáb pokořen pod mocí Izraele a země měla osmdesát let klid.',
        31: 'Po něm byl Šamgar, syn Anatův. Pobil Pelištejce, šest set mužů, bodcem na skot. Také on zachránil Izrael.',
    },
    4: {
        1: 'Synové Izraele však dále páchali to, co je zlé v Hospodinových očích. Ehúd zemřel.',
        2: 'Hospodin je vydal do ruky kenaanského krále Jabína, jenž kraloval v Chasóru, a velitele jeho armády Sísery sídlícího v Charošet–hagójímu.',
        3: 'A synové Izraele křičeli k Hospodinu. Vždyť Jabín měl devět set železných vozů a dvacet let syny Izraele násilím utlačoval.',
        4: 'V oné době soudila Izrael Debóra, prorokyně, žena Lapidótova.',
        5: 'Ta sedávala pod Debóřinou palmou mezi Rámou a Bét–elem v efrajimském pohoří. Synové Izraele za ní přicházeli k soudu.',
        6: 'Ta poslala a povolala Báraka, syna Abínoamova, z neftalíjské Kedeše, a řekla mu: Což nepřikázal Hospodin, Bůh Izraele: Jdi, vytáhneš na horu Tábor a vezmeš s sebou deset tisíc mužů ze synů Neftalího a ze synů Zabulóna?',
        7: 'Já k tobě přivedu k potoku Kíšón Síseru, velitele Jabínovy armády, jeho vozy a jeho dav a vydám ti ho do ruky.',
        8: 'Bárak jí odpověděl: Pokud půjdeš se mnou, i já půjdu. Nepůjdeš–li se mnou, nepůjdu ani já.',
        9: 'Ona řekla: Určitě půjdu s tebou, jenomže na cestě, po které ty půjdeš, ti nebude patřit sláva, protože Hospodin vydá Síseru do ruky ženy. Debóra vstala a šla s Bárakem do Kedeše.',
        10: 'Bárak svolal Zabulóna a Neftalího do Kedeše. ⌈V jeho stopách⌉ vytáhlo deset tisíc mužů. Debóra vytáhla s ním.',
        11: 'A Kénijec Cheber se odloučil od Kajina, od synů Mojžíšova tchána Chóbaba, a postavil svůj stan až k dubu v Saananímu, který je u Kedeše.',
        12: 'Síserovi oznámili, že Bárak, syn Abínoamův, vystoupil na horu Tábor.',
        13: 'Sísera svolal veškerou svou vozbu, devět set železných vozů, a všechen lid, který byl s ním, z Charošet–hagójímu k potoku Kíšón.',
        14: 'Debóra řekla Bárakovi: Vstaň, protože toto je den, v němž Hospodin vydal Síseru do tvé ruky. Cožpak nevyšel Hospodin před tebou? A Bárak sestoupil z hory Tábor a za ním deset tisíc mužů.',
        15: 'Hospodin přivedl před Bárakem do zmatku Síseru a celou vozbu a celý tábor na ostří meče. Sísera sestoupil z válečného vozu a utíkal pěšky.',
        16: 'A Bárak pronásledoval vozbu a vojsko až do Charošet–hagójímu. Celé Síserovo vojsko padlo ostřím meče; nezůstal ani jediný.',
        17: 'A Sísera utíkal pěšky ke stanu Jáely, ženy Kénijce Chebera, protože mezi chasórským králem Jabínem a domem Kénijce Chebera vládl pokoj.',
        18: 'Jáel vyšla Síserovi naproti a řekla mu: Zajdi, můj pane, zajdi ke mně, neboj se. Zašel tedy k ní do stanu a ona jej přikryla houní.',
        19: 'Řekl jí: Dej mi prosím napít trochu vody, protože mám žízeň. Otevřela měch s mlékem, dala mu napít a přikryla jej.',
        20: 'Řekl jí: Postav se u vchodu do stanu, a když někdo přijde, bude se tě vyptávat a řekne: Není tu někdo? Odpovíš: Není.',
        21: 'Jáel, žena Cheberova, vzala stanový kolík a do ruky uchopila kladivo. Přišla potají k němu a vrazila mu ten kolík do spánku, až proniknul do země. On tvrdě spal, byl totiž unavený; tak zemřel.',
        22: 'A hle, Bárak pronásledoval Síseru. Jáel mu vyšla naproti a řekla mu: Pojď, ukážu ti muže, kterého hledáš. Vešel k ní a hle, Sísera leží mrtev a ve spánku má kolík.',
        23: 'V onen den Bůh pokořil kenaanského krále Jabína před syny Izraele.',
        24: 'Ruka synů Izraele doléhala stále a tvrdě na kenaanského krále Jabína, až i kenaanského krále Jabína vyhladili.',
    },
    5: {
        1: 'V onen den zpívala Debóra a Bárak, syn Abínoamův:',
        2: 'Když jsou v Izraeli volně rozpuštěné vlasy, když se lid dobrovolně rozhodl, dobrořečte Hospodinu!',
        3: 'Slyšte králové, naslouchejte mocnáři! Já Hospodinu, já jemu chci zpívat. Budu opěvovat Hospodina, Boha Izraele.',
        4: 'Hospodine, když jsi vycházel ze Seíru, když jsi vykročil z edómské krajiny, třásla se země a také z nebes kanula, ano z mračen kanula voda.',
        5: 'Hory se potácely před Hospodinem, tím ze Sínaje, před Hospodinem, Bohem Izraele.',
        6: 'Ve dnech Šamgara, syna Anatova, ve dnech Jáely, zpustly stezky a poutníci na pěšinách chodili stezkami křivolakými.',
        7: 'Vymizeli venkované v Izraeli, vymizeli až do chvíle, kdy jsem povstala já, Debóra, kdy jsem povstala, matka v Izraeli.',
        8: 'Zvolí– li si nové bohy, tehdy je válka v branách. Zdalipak se ukáže štít a oštěp mezi čtyřiceti tisíci v Izraeli?',
        9: 'Mé srdce je s veliteli Izraele, s dobrovolníky z lidu. Dobrořečte Hospodinu!',
        10: 'Vy, kdo jezdíte na bělavých oslicích, vy, kdo sedáváte na kobercích, i vy, poutníci na cestě, přemýšlejte.',
        11: 'Daleko od hlasu střelců mezi napajedly, tam si budou připomínat Hospodinovy spravedlivé činy, spravedlivé činy vůči jeho venkovanům v Izraeli. Tehdy sestoupil k branám Hospodinův lid.',
        12: 'Probuď se, probuď, Debóro, probuď se, probuď, přednes píseň. Vstaň, Báraku, a zajmi své zajatce, synu Abínoamův.',
        13: 'Tehdy sestoupil ten, který přežil, k vznešeným. Hospodinův lid sestoupil ke mně jako hrdinové.',
        14: 'Z Efrajima vyšli ti, jejichž kořen byl v Amálekovi. Za tebou šel Benjamín s tvým lidem. Z Makíra sestoupili velitelé a ze Zabulóna ti, kdo nosí velitelské žezlo.',
        15: 'A má knížata z Isachara šla spolu s Debórou; Isachar stejně jako Bárak byl poslán v jeho stopách do údolí. V Rúbenových oddílech byla velká vymezování mínění.',
        16: 'Proč jsi zůstal mezi ohradami? Abys naslouchal hvízdání na stáda? Rúbenovy oddíly měly velká zpytování mínění.',
        17: 'Gileád se usídlil na druhé straně Jordánu. A proč Dan pobývá na lodích? Ašer se usadil na pobřeží moře, bydlí nad svými přístavy.',
        18: 'Zabulón je lid, který vydal svou duši na smrt. Rovněž Neftalí na výšinách krajiny.',
        19: 'Přišli králové a bojovali. Tehdy bojovali kenaanští králové v Taanaku u vod Megida. Nekalý zisk stříbra nepobrali.',
        20: 'Z nebes bojovaly hvězdy, ze svých drah bojovaly se Síserou.',
        21: 'Potok Kíšón je odplavil, potok prastarý, potok Kíšón. Šlapej, má duše, mocně.',
        22: 'Tehdy se otloukla koňská kopyta od dusání, dusání jeho hřebců.',
        23: 'Proklejte Meróz, praví Hospodinův anděl, prokletím proklejte jeho obyvatele, protože nepřišli na pomoc Hospodinu, na pomoc Hospodinu jako hrdinové.',
        24: 'Požehnána buď mezi ženami Jáel, žena Kénijce Chebera, mezi ženami ve stanu buď požehnána.',
        25: 'On si vyžádal vodu, ona mu dala mléko, smetanu podala ve džbánu vznešených.',
        26: 'Rukou svou po kolíku sáhla a pravicí svou na kladivo pro těžce pracující a udeřila Síseru. Roztříštila mu hlavu, probodla a prorazila mu spánek.',
        27: 'Mezi nohama jí klesl, padl, složil se. Mezi nohama jí klesl, padl. Kde klesl, tam padl zmordovaný.',
        28: 'Za oknem vyhlížela, za okenní mříží naříkala Síserova matka: Proč otálí jeho vůz s příjezdem, proč se opozdila kola jeho válečných vozů?',
        29: 'Její moudré kněžny jí odpovědí, ona si také bude připomínat své řeči.',
        30: 'Cožpak nenaleznou a ne budou dělit kořist? ⌈Souložnici nebo dvě⌉ ⌈pro každého předáka,⌉ kořist -- barvené šaty pro Síseru, kořist -- utkané barvené šaty, utkané barvené šaty ⌈na šíje,⌉ kořist.',
        31: 'Tak ať zahynou všichni tví nepřátelé, Hospodine, ale ti, kdo jej milují, budou jako slunce vycházející ve své síle. Země měla čtyřicet let klid.',
    },
    6: {
        1: 'Synové Izraele pak páchali to, co je zlé v Hospodinových očích a Hospodin je vydal do ruky Midjánců na sedm let.',
        2: 'Ruka Midjánců mocně dolehla na Izrael. Synové Izraele pro sebe kvůli Midjáncům upravili soutěsky, které byly v horách, jeskyně a pevnosti.',
        3: 'Když Izrael zasel, stávalo se, že vytáhli Midjánci, Amálekovci a synové východu a vyrazili proti němu.',
        4: 'Utábořili se proti nim a ničili úrodu země, až tam, kudy se jde do Gazy a neponechali v Izraeli obživu, ovci, býka ani osla.',
        5: 'Neboť oni vytáhli se svým dobytkem a svými stany a přihnali se jako celé hejno kobylek. Bylo jich i jejich velbloudů bezpočet a přišli do země, aby ji zničili.',
        6: 'Izrael byl od Midjánců úplně zubožený. Synové Izraele volali k Hospodinu o pomoc.',
        7: 'I stalo se, že synové Izraele volali k Hospodinu o pomoc kvůli Midjáncům',
        8: 'a Hospodin poslal k synům Izraele proroka. Ten jim řekl: Toto praví Hospodin, Bůh Izraele: Já jsem vás vyvedl z Egypta, vyvedl jsem vás z domu otroctví.',
        9: 'Vysvobodil jsem vás z ruky Egypťanů a z ruky všech vašich utiskovatelů, vyhnal jsem je před vámi a dal jsem vám jejich zemi.',
        10: 'A řekl jsem vám: Já Hospodin jsem váš Bůh, nebojte se bohů Emorejců, v jejichž zemi bydlíte. Ale neuposlechli jste mě.',
        11: 'I přišel Hospodinův anděl a posadil se pod terebintem, který je v Ofře, která patří Jóašovi Abíezerskému. Jeho syn Gedeón mlátil pšenici v lisu na víno, aby ji uchránil před Midjánci.',
        12: 'Hospodinův anděl se mu ukázal a řekl mu: Hospodin s tebou, udatný hrdino.',
        13: 'Nato mu Gedeón odpověděl: Dovol, můj pane, pokud je Hospodin s námi, proč nás potom postihlo toto všechno a kde jsou všechny jeho obdivuhodné činy, o kterých nám vyprávěli naši otcové, když říkali: Cožpak nás Hospodin nevyvedl z Egypta? Jenže teď nás Hospodin opustil a vydal nás do ruky Midjánců.',
        14: 'Hospodin se k němu obrátil a řekl: Jdi v této své síle a zachráníš Izrael z ruky Midjánců. Což jsem tě neposlal?',
        15: 'On se ho zeptal: Dovol, Panovníku, čím zachráním Izrael? Vždyť můj rod je v Manasesovi nejslabší a já jsem ten nejmenší v domě svého otce.',
        16: 'Tu mu Hospodin odpověděl: Protože budu s tebou, pobiješ Midjánce jako jediného muže.',
        17: 'On jej požádal: Jestliže jsem opravdu nalezl milost ve tvých očích, učiň pro mě znamení, že se mnou mluvíš ty.',
        18: 'Nevzdaluj se, prosím, odsud, dokud se k tobě ne vrátím, ne přinesu svou přídavnou oběť a ne předložím ti ji. Řekl mu: Já zůstanu dokud se nevrátíš.',
        19: 'Gedeón tedy šel a připravil kůzle a nekvašené chleby z éfy mouky. Maso položil do koše, vývar nalil do hrnce, přinesl to k němu pod terebint a nabídl mu to.',
        20: 'Boží anděl mu řekl: Vezmi to maso a nekvašené chleby, předlož to u této skály, ale vývar vylej. I učinil tak.',
        21: 'Hospodinův anděl vztáhl konec hole, kterou měl v ruce, a dotkl se masa a nekvašených chlebů. Ze skály vystoupil oheň a strávil to maso a nekvašené chleby. Hospodinův anděl mu pak zmizel z očí.',
        22: 'Gedeón zjistil, že to byl Hospodinův anděl. Gedeón řekl: Běda mi, Panovníku Hospodine, protože jsem spatřil Hospodinova anděla tváří v tvář.',
        23: 'Hospodin mu však odpověděl: Pokoj tobě, neboj se, nezemřeš.',
        24: 'Gedeón tam postavil Hospodinu oltář a nazval jej: Hospodin je pokoj. Až do tohoto dne je stále v Abíezerské Ofře.',
        25: 'I stalo se oné noci, že mu Hospodin řekl: Vezmi býčka, býka, který patří tvému otci, ba toho druhého sedmiletého býčka. Zboříš Baalův oltář, který patří tvému otci, a pokácíš posvátný kůl, který je u něj.',
        26: 'Dále postavíš patřičným způsobem oltář Hospodinu, svému Bohu, na vrcholu této skály. Vezmeš toho druhého býčka a přineseš zápalnou oběť na dříví z toho posvátného kůlu, který pokácíš.',
        27: 'Gedeón vzal deset mužů ze svých otroků a učinil, jak mu Hospodin pověděl. I stalo se, protože se to kvůli domu svého otce a kvůli mužům toho města bál provést ve dne, že to vykonal v noci.',
        28: 'Muži města časně ráno vstali a hle: Baalův oltář byl stržen a posvátný kůl, jenž u něj stával, byl skácen a druhý býček byl obětovaný na oltáři, který tu byl vybudován.',
        29: 'Tu se ptali jeden druhého: Kdo provedl něco takového? Pátrali, hledali a řekli: Tohle provedl Gedeón, syn Jóášův.',
        30: 'Nato řekli muži toho města Jóašovi: Vyveď svého syna. Ať zemře, protože strhl Baalův oltář a pokácel posvátný kůl, který byl u něj.',
        31: 'Ale Jóaš odpověděl všem, kteří se proti němu postavili: Cožpak vy ⌈povedete při za⌉ Baala? Vy ho snad budete zachraňovat? Kdo za něho povede při, bude do rána usmrcen. Jestliže on je bůh, povede při za sebe; strhl přece jeho oltář.',
        32: 'I nazval jej v onen den Jerubaalem se slovy: Ať s ním vede při Baal, vždyť mu strhl oltář.',
        33: 'Tehdy se všichni Midjánci, Amálekovci a synové východu společně shromáždili, přebrodili a utábořili v údolí Jizreel.',
        34: 'A Duch Hospodinův vyzbrojil Gedeóna. Ten zatroubil na beraní roh a Abíezerovci se za ním shromáždili.',
        35: 'Poslal posly po celém Manasesovi a on se také shromáždil za ním; poslal posly i k Ašerovi, k Zabulónovi a k Neftalímu a vyšli jim naproti.',
        36: 'Potom Gedeón Bohu řekl: Jestliže ⌈chceš zachránit⌉ Izrael mým prostřednictvím, jak jsi to prohlásil,',
        37: 'hle, pokládám na humno ovčí rouno. Pokud bude rosa pouze na tom rouně a všude na zemi sucho, poznám, že mým prostřednictvím zachráníš Izrael, jak jsi to prohlásil.',
        38: 'I stalo se tak. Příštího dne časně vstal a vymačkal rouno. Vyždímal z toho rouna rosu, plný džbán vody.',
        39: 'Avšak Gedeón Bohu řekl: Kéž proti mně nevzplane tvůj hněv. Nech mě promluvit ještě jednou. Dovol, prosím, abych to zkusil s rounem už jen jednou. Nechť je, prosím, suché pouze to rouno a ⌈všude na⌉ zemi je rosa.',
        40: 'A Bůh tak oné noci učinil. Samo rouno bylo suché, kdežto všude na zemi byla rosa.',
    },
    7: {
        1: 'Časně ráno vstal Jerubaal, tedy Gedeón, a všechen lid, který byl s ním, a utábořili se u Én–charódu. Tábor Midjánců byl u něho v údolí severně od návrší Móre.',
        2: 'Hospodin však Gedeónovi řekl: Je s tebou příliš mnoho lidu, než abych dal Midjánce do jejich ruky. Jinak by se Izrael vůči mně vychloubal: Zachránila mě má ruka.',
        3: 'A teď k lidu ihned provolej: Kdo se bojí a třese, ať se vrátí a vzdálí z pohoří Gileádu. Nato se vrátilo z lidu dvacet dva tisíce a deset tisíc zůstalo.',
        4: 'Ale Hospodin Gedeónovi řekl: Ještě je lidu mnoho. Nech je sestoupit k vodě, ať ti je tam přečistím. I stane se toto: O kom ti řeknu: Tenhle půjde s tebou, ten s tebou půjde, a každý, o kom ti řeknu: Tenhle s tebou nepůjde, ten nepůjde.',
        5: 'Nechal tedy sestoupit lid k vodě a Hospodin Gedeónovi řekl: Každého, kdo bude chlemtat vodu jazykem, tak jako chlemtá pes, toho postavíš zvlášť a také každého, kdo si klekne k pití na kolena.',
        6: 'Počet chlemtajících, kteří si podávali rukou do úst, byl tři sta mužů. Všechen ostatní lid si k pití vody klekl na kolena.',
        7: 'Nato Hospodin Gedeónovi řekl: Prostřednictvím těch tří set chlemtajících mužů vás zachráním a vydám Midjánce do tvé ruky. Všechen lid ať odejde, každý do svého domova.',
        8: 'Ti, kdo zůstali, si vzali s sebou zásobu potravin lidu a jejich beraní rohy. Všechny izraelské muže poslal pryč, každého k jeho stanům. Podržel si jenom tři sta mužů. Midjánský tábor byl pod ním v údolí.',
        9: 'I stalo se oné noci, že mu Hospodin řekl: Vstaň, sestup do tábora, protože jsem ti ho vydal do ruky.',
        10: 'A pokud se bojíš sestoupit sám, sestup do tábora se svým služebníkem Púrou',
        11: 'a uslyšíš, co budou mluvit. Potom se posilní tvé ruce a sestoupíš do tábora. Sestoupil tedy on i jeho služebník Púra ke kraji ⌈vojenských oddílů,⌉ které byly v táboře.',
        12: 'Midjánců, Amálekovců a všech synů východu ležících v údolí bylo co do množství jako kobylek a jejich velbloudů co do množství bylo bezpočet jako písku, který je na mořském břehu.',
        13: 'Gedeón přišel a hle, muž vypráví svému příteli sen. Říkal: Poslyš, měl jsem sen a v něm se valí pecen ječného chleba na midjánský tábor až ke stanu a udeřil do něj, až spadl, převrátil ho vzhůru nohama a ten stan se zhroutil.',
        14: 'Jeho přítel odpověděl. Řekl: Tohle neznamená nic jiného než meč izraelského muže Gedeóna, syna Jóášova. Bůh mu vydal do ruky Midjánce i celý tábor.',
        15: 'I stalo se, jakmile Gedeón uslyšel vyprávění toho snu a jeho výklad, že se poklonil. Vrátil se do izraelského tábora a řekl: Vstaňte, protože Hospodin vydal midjánský tábor do vaší ruky.',
        16: 'Rozdělil tři sta mužů do tří oddílů, dal jim všem do ruky beraní rohy, prázdné džbány a uvnitř těch džbánů byly pochodně.',
        17: 'A řekl jim: Sledujte mě a dělejte to stejně jako já. Hle, půjdu na kraj tábora a bude to tak, ⌈že co⌉ udělám já, uděláte stejně i vy.',
        18: 'Až zatroubím na beraní roh já a všichni, kdo jsou se mnou, zatroubíte také vy na beraní rohy okolo celého tábora a zavoláte: Za Hospodina a za Gedeóna.',
        19: 'Gedeón přišel se stem mužů, kteří byli s ním, na kraj tábora na počátku prostřední noční hlídky, ⌈jakmile zcela postavili⌉ stráže. Zatroubili na beraní rohy a rozbili džbány, které měli v rukou.',
        20: 'I tři oddíly zatroubily na beraní rohy, rozbily džbány a uchopily do levé ruky pochodně a do pravé ruky beraní rohy, aby troubily, a zavolaly: Meč za Hospodina a za Gedeóna.',
        21: 'Postavili se každý na své místo okolo tábora a celý tábor běžel, křičeli a utíkali.',
        22: 'Tři sta beraních rohů troubilo a Hospodin obrátil meč ⌈jednoho proti druhému,⌉ a to v celém táboře. Tábor utíkal až do Bét–šity k Seréře, až k břehu Ábel–mechóly u Tabbátu.',
        23: '⌈Byli svoláni izraelští muži⌉ z Neftalího, z Ašera a z celého Manasesa a pronásledovali Midjánce.',
        24: 'Gedeón poslal posly po celém efrajimském pohoří se slovy: Sestupte vstříc Midjáncům a obsaďte jim vody až k Bét–báře a Jordán. ⌈Byli svoláni všichni efrajimští muži⌉ a obsadili vody až k Bét–báře a Jordán.',
        25: 'Přitom zajali dvě midjánská knížata, Óréba a Zéba. Oréba zabili na Cúr Órébu a Zéba zabili v Jekeb Zébu. Pronásledovali Midjánce a hlavu Óréba a Zéba přinesli Gedeónovi přes Jordán.',
    },
    8: {
        1: 'Avšak efrajimští muži mu řekli: ⌈Jak jsi to s námi jednal,⌉ že jsi nás nezavolal, když jsi šel do boje s Midjánci? A silně se s ním přeli.',
        2: 'Nato jim odpověděl: Co jsem teď učinil takového jako vy? Což nejsou Efrajimovy paběrky lepší než Abíezerovo vinobraní?',
        3: 'Do vaší ruky dal Bůh midjánská knížata Óréba a Zéba. Co jsem mohl udělat jako vy? Tehdy ochabl jejich hněv proti němu, ⌈když promluvil tato slova.⌉',
        4: 'Gedeón přišel k Jordánu a prošel jím se třemi sty muži, kteří byli s ním, vyčerpaní, pronásledující nepřítele.',
        5: 'Požádal tedy muže ze Sukótu: Dejte, prosím, po bochníku chleba lidu, který jde v mých stopách, protože jsou vyčerpaní. Pronásleduji midjánské krále Zebacha a Salmunu.',
        6: 'Ale sukótská knížata odpověděla? Cožpak je pěst Zebacha a Salmuny již ve tvé ruce, že máme dát tvé armádě chléb?',
        7: 'Nato Gedeón řekl: Za tohle zmlátím vaše tělo stepním trním a bodláky, až dá Hospodin Zebacha a Salmunu do mé ruky.',
        8: 'Vystoupil odtamtud do Penúelu a promluvil k nim podobně. Muži z Penúelu mu odpověděli stejně, jako odpověděli muži sukótští.',
        9: 'Také mužům v Penúelu řekl: Až se v pokoji navrátím, strhnu tuto věž.',
        10: 'Zebach a Salmuna byli v Karkóru a s nimi jejich vojska, okolo patnácti tisíc, všichni, kteří zbyli z celého vojska synů východu. Padlých bylo sto dvacet tisíc mužů schopných tasit meč.',
        11: 'Gedeón vytáhl cestou těch, kdo přebývají ve stanech na východ od Nóbachu a Jogbohy, a přepadl tábor, právě když ten tábor spočíval v bezpečí.',
        12: 'Zebach a Salmuna utíkali a on je pronásledoval. Zajal oba midjánské krále, Zebacha a Salmunu, a celé vojsko uvedl v paniku.',
        13: 'Když se Gedeón, syn Jóášův, vracel z té bitvy ⌈od svahu Cheresu,⌉',
        14: 'zajal mládence ze sukótských mužů, vyptával se ho a on pro něho sepsal knížata Sukótu a jeho starší, sedmdesát sedm mužů.',
        15: 'Pak přišel k sukótským mužům a řekl: Zde jsou Zebach a Salmuna, pro které jste mě hanobili slovy: Cožpak je pěst Zebacha a Salmuny již ve tvé ruce, že máme dát tvým unaveným mužům chléb?',
        16: 'A vzal starší toho města a stepní trní a bodláky a dal jimi sukótským mužům ⌈za vyučenou.⌉',
        17: 'Strhl i věž v Penúelu a zabil muže toho města.',
        18: 'Potom se zeptal Zebacha a Salmuny: Jak vypadali ti muži, které jste zabili na Táboře? Odpověděli: Jaký jsi ty, takoví byli oni, všichni podle vzezření královští synové.',
        19: 'On řekl: To byli mí bratři, synové mé matky. Jakože živ je Hospodin: Kdybyste je nechali žít, nezabil bych vás.',
        20: 'A Jeterovi, svému prvorozenému, řekl: Vstaň, zabij je. Ale ten chlapec nevytáhl svůj meč, neboť se bál. Byl totiž ještě malý.',
        21: 'Tu řekl Zebach a Salmuna: Vstaň ty a zasáhni nás, vždyť ⌈jaký muž, taková jeho síla.⌉ Gedeón tedy vstal, zabil Zebacha a Salmunu a vzal si půlměsíčky, které měli na šíjích jejich velbloudi.',
        22: 'Izraelští muži pak Gedeónovi řekli: Vládni nad námi ty i tvůj syn a také ⌈tvůj vnuk,⌉ protože jsi nás zachránil z ruky Midjánců.',
        23: 'Ale Gedeón jim odpověděl: Nebudu nad vámi vládnout já, ani můj syn nad vámi ne bude vládnout. Nad vámi bude vládnout Hospodin.',
        24: 'Gedeón jim dále řekl: Dovolte mi přednést vám prosbu: Dejte mi každý kroužek ze své kořisti. Měli totiž zlaté kroužky, protože tamti byli Izmaelité.',
        25: 'Oni odpověděli: Rádi dáme. Rozprostřeli plášť a hodili tam všichni kroužek ze své kořisti.',
        26: 'Váha těch zlatých kroužků, které si vyžádal, byla tisíc sedm set šekelů zlata mimo ty půlměsíčky, náušnice a roucha z purpuru, která měli na sobě midjánští králové, a mimo náhrdelníky, které visely na šíjích jejich velbloudů.',
        27: 'Gedeón ⌈z toho udělal efód,⌉ postavil ho ve svém městě, v Ofře, a všichni z Izraele tam za ním chodili smilnit, takže se stal Gedeónovi a jeho domu léčkou.',
        28: 'Tehdy byli Midjánci před syny Izraele pokořeni a již nepozdvihli hlavu. Země měla v Gedeónových dnech čtyřicet let klid.',
        29: 'Jerubaal, syn Jóášův, pak odešel a usadil se ve svém domě.',
        30: 'Gedeón měl dále sedmdesát synů, vzešlých z jeho beder, protože měl mnoho žen.',
        31: 'Také jeho konkubína, kterou měl v Šekemu, mu porodila syna a tomu dal jméno Abímelek.',
        32: 'Nakonec Gedeón, syn Jóášův, zemřel v utěšených šedinách a byl pohřben do hrobu svého otce Jóaše v Abíezerské Ofře.',
        33: 'I stalo se, jakmile Gedeón zemřel, že se synové Izraele odvrátili, chodili smilnit za baaly a ustanovili Baal–beríta svým bohem.',
        34: 'Synové Izraele si nepamatovali na Hospodina, svého Boha, který je vysvobozoval z ruky všech jejich okolních nepřátel.',
        35: 'Ani ne prokázali milosrdenství domu Jerubaala Gedeóna za veškeré dobro, jež vykonal pro Izrael.',
    },
    9: {
        1: 'Abímelek, syn Jerubaalův, pak šel do Šekemu k bratrům své matky a promluvil k nim a ke vší čeledi z domu rodu své matky:',
        2: 'Promluvte prosím ke všem občanům Šekemu: Co je pro vás lepší? Má nad vámi vládnout sedmdesát mužů, samí synové Jerubaalovi? Co kdyby nad vámi vládl jediný muž? Vzpomeňte si, že jsem vaše kost a vaše tělo.',
        3: 'Když o něm bratři jeho matky promluvili ke všem občanům Šekemu všechna tato slova, jejich srdce se naklonilo za Abímelekem, protože si řekli: Je to náš bratr.',
        4: 'Dali mu sedmdesát šekelů stříbra z chrámu Baal–beríta a Abímelek si za ně najal ničemné a bezohledné muže, kteří ho následovali.',
        5: 'A přišel do Ofry, do domu svého otce, a zabil své bratry, syny Jerubaalovy, sedmdesát mužů na jednom kameni. Zůstal Jótam, nejmladší syn Jerubaalův, protože se ukryl.',
        6: 'Pak se shromáždili všichni občané Šekemu a celé Bét–miló. Šli a ustanovili Abímeleka za krále u dubu, který stojí v Šekemu.',
        7: 'Když to oznámili Jótamovi, šel a postavil se na vrchol hory Gerizím, pozvedl svůj hlas a zavolal. Řekl jim: Poslouchejte mě, občané Šekemu, a vás nechť vyslechne Bůh.',
        8: 'Tak se jednou sešly stromy, aby nad sebou pomazaly krále, a řekly olivě: Kraluj nad námi.',
        9: 'Oliva jim však pravila: Cožpak bych se vzdala své tučnosti, pro kterou mě oslavují bohové i lidé, a šla se kymácet nad stromy?',
        10: 'Stromy tedy řekly fíkovníku: Pojď ty, kraluj nad námi.',
        11: 'I fíkovník jim odpověděl: Cožpak bych se vzdal své sladkosti a svého dobrého ovoce a šel se kymácet nad stromy?',
        12: 'Nato řekly stromy révě: Pojď ty, kraluj nad námi.',
        13: 'Rovněž réva jim pravila: Cožpak bych se vzdala svého mladého vína, které dává radost bohům i lidem, a šla se kymácet nad stromy?',
        14: 'Ještě řekly všechny stromy bodláku: Pojď ty, kraluj nad námi.',
        15: 'A bodlák stromům odpověděl: Jestliže mě opravdu chcete pomazat za krále nad sebou, přijďte a schovejte se v mém stínu. Pokud ne, ať vyjde z bodláku oheň a stráví libanonské cedry.',
        16: 'Nyní, jestliže jste si počínali věrně a bezúhonně, když jste ustanovili Abímeleka králem, pokud jste prokázali dobro Jerubaalovi a jeho domu a naložili jste s ním ⌈podle toho, co vykonaly jeho ruce,⌉',
        17: '-- můj otec přece bojoval za vás, ⌈dal v sázku svou duši⌉ a vysvobodil vás z ruky Midjánců,',
        18: 'ale vy jste dnes povstali proti domu mého otce, zabili jste jeho syny, sedmdesát mužů, na jednom kameni a králem nad občany Šekemu jste ustanovili Abímeleka, syna jeho služebnice, protože je to váš bratr --',
        19: 'jestliže jste tedy věrně a bezúhonně jednali s Jerubaalem a s jeho domem tohoto dne, radujte se z Abímeleka a také on ať se raduje z vás.',
        20: 'Pokud tomu tak není, ať vyjde z Abímeleka oheň a stráví občany Šekemu a Bét–miló a ať vyjde oheň z občanů Šekemu a z Bét–miló a stráví Abímeleka.',
        21: 'Potom Jótam utekl, prchal pryč od svého bratra Abímeleka, odešel do Beéru a bydlel tam.',
        22: 'Abímelek vládl nad Izraelem tři roky.',
        23: 'Bůh pak poslal mezi Abímeleka a občany Šekemu zlého ducha a občané Šekemu se k Abímelekovi zachovali zrádně.',
        24: 'To pro násilí spáchané na sedmdesáti Jerubaalových synech, aby jejich krev dopadla na jejich bratra Abímeleka, který je zabil, a na občany Šekemu, kteří posilnili jeho ruce, aby zabil své bratry.',
        25: 'Občané Šekemu mu nastražili zálohy na vrcholech hor a okrádali každého, kdo procházel po cestě kolem nich. Abímelekovi to bylo oznámeno.',
        26: 'Tehdy přišel Gaal, syn Ebedův, a jeho bratři a procházeli Šekemem. Občané Šekemu mu důvěřovali.',
        27: 'Vyšli na pole a sbírali víno ze svých vinic, šlapali ho a uspořádali slavnost. Vstoupili do chrámu svého boha, jedli a pili a proklínali Abímeleka.',
        28: 'Tehdy řekl Gaal, syn Ebedův: Kdo je Abímelek a kdo jsou ⌈šekemští, že jim⌉ budeme sloužit? Což to není syn Jerubaalův a není Zebúl jeho dohlížitel? Služte mužům Chamóra, otce Šekemova. Proč my máme sloužit jemu?',
        29: '⌈Kéž bych měl tento lid pod svým velením,⌉ abych Abímeleka odstranil! Abímelekovi řekl: Rozmnož svou armádu a vytáhni.',
        30: 'Když Zebúl, kníže města, uslyšel slova Gaala, syna Ebedova, vzplanul jeho hněv.',
        31: 'A poslal k Abímelekovi tajně posly se slovy: Hle Gaal, syn Ebedův, a jeho bratři přicházejí do Šekemu. Pozor na ně! Pobuřují město proti tobě.',
        32: 'Nuže, vstaň v noci, ty i lid, který je s tebou, a nastraž v poli zálohu.',
        33: 'A časně ráno, jakmile vyjde slunce, vstaneš, vtrhneš do města a hle, on a lid, jenž je s ním, vytáhne ⌈proti tobě⌉ a ty s ním naložíš, ⌈jak se ti namane⌉.',
        34: 'V noci tedy Abímelek a všechen lid, který byl s ním, vstal a nastražili na Šekem zálohu -- čtyři oddíly.',
        35: 'Když Gaal, syn Ebedův, vyšel a postavil se do vchodu městské brány, Abímelek a lid, který byl s ním, vstal ze zálohy.',
        36: 'Gaal ten lid spatřil a řekl Zebúlovi: Podívej se, lid sestupuje z vrcholů hor. Ale Zebúl mu odpověděl: Vidíš jen stín hor, podobný mužům.',
        37: 'Gaal však ⌈mluvil stále dál.⌉ Řekl: Hle, lid sestupuje ze ⌈středu země⌉ a jeden oddíl přichází od cesty k dubu věštců.',
        38: 'Nato mu Zebúl řekl: Kde jsou tedy tvá ústa, kterými jsi prohlásil: Kdo je Abímelek, že mu máme sloužit? Cožpak tohle není ten lid, kterým jsi kvůli němu pohrdl? Vytáhni už konečně a bojuj proti němu.',
        39: 'Gaal tedy vytáhl v čele šekemských občanů a bojoval proti Abímelekovi.',
        40: 'Abímelek jej však pronásledoval a on před ním utekl. Padlo mnoho probodených až po vchod do brány.',
        41: 'Abímelek se usadil v Arúmě a Zebúl Gaala a jeho bratry vyhnal, takže nezůstali v Šekemu.',
        42: 'I stalo se příštího dne, že lid vyšel na pole. Oznámili to Abímelekovi.',
        43: 'Ten vzal lid, rozdělil je do tří oddílů a v poli nastražil zálohu. Rozhlédl se a hle, lid vychází z města. Povstal proti nim a pobil je.',
        44: 'Abímelek a oddíly, které byly s ním, vtrhly a postavily se ke vchodu do městské brány. Další dva oddíly pak vtrhly na všechny, kdo byli na poli, a pobily je.',
        45: 'Abímelek proti městu bojoval celý den, dobyl to město a lid, jenž byl v něm, zabil. Město zbořil a posypal ho solí.',
        46: 'Když to uslyšeli všichni občané šekemské věže, vešli do sklepení chrámu El–beríta.',
        47: 'Abímelekovi bylo oznámeno, že se shromáždili všichni občané šekemské věže.',
        48: 'Tu Abímelek vystoupil na horu Salmón, on i všechen lid, který byl s ním. Abímelek ⌈s sebou⌉ vzal sekery, usekl větev ze stromu, zvedl ji a položil si ji na rameno. Lidu, který byl s ním, řekl: Co jste viděli, že jsem udělal, pospěšte si a udělejte to jako já.',
        49: 'Také všechen lid tedy usekl každý svou větev, šli za Abímelekem, položili je na sklepení a zapálili nad nimi ⌈ na tom sklepení oheň.⌉ Tak zemřeli také všichni lidé ze šekemské věže, asi tisíc mužů a žen.',
        50: 'Potom šel Abímelek do Tebesu, utábořil se u Tebesu a dobyl jej.',
        51: 'Uprostřed toho města byla pevná věž. Tam utekli všichni muži a ženy, všichni občané města, zavřeli za sebou a vystoupili na střechu té věže.',
        52: 'Abímelek přišel k věži, bojoval proti ní a přistoupil až ke vchodu té věže, aby ji spálil ohněm.',
        53: 'Vtom svrhla jedna žena Abímelekovi na hlavu vrchní mlýnský kámen a prorazila mu lebku.',
        54: 'Rychle zavolal na služebníka, svého zbrojnoše, a řekl mu: Vytáhni svůj meč a usmrť mě. Jinak o mně budou říkat: Zabila jej žena. Jeho služebník jej tedy probodnul a on zemřel.',
        55: 'Když izraelští muži viděli, že Abímelek zemřel, odešli každý do svého domova.',
        56: 'Tak Bůh odplatil Abímelekovi za zlo, jež spáchal proti svému otci, když zabil svých sedmdesát bratrů.',
        57: 'Také všechno zlo šekemských mužů Bůh obrátil na jejich hlavu a přišla na ně kletba Jótama, syna Jerubaalova.',
    },
    10: {
        1: 'Po Abímelekovi pak povstal k záchraně Izraele isacharský muž Tóla, syn Púy, syna Dódova. Ten bydlel v Šamíru v efrajimském pohoří.',
        2: 'Soudil Izrael dvacet tři let. Zemřel a byl pohřben v Šamíru.',
        3: 'Po něm povstal Jaír Gileádský a soudil Izrael dvacet dva let.',
        4: 'Ten měl třicet synů, jezdících na třiceti oslech a patřilo jim třicet měst. Podle nich nazývají Jaírova tábořiště, která jsou v zemi Gileádu, až do tohoto dne.',
        5: 'Jaír zemřel a byl pohřben v Kamónu.',
        6: 'A synové Izraele dále páchali to, co je zlé v Hospodinových očích, sloužili baalům a aštoretám, bohům aramejským, bohům sidónským, bohům moábským, bohům synů Amónových a bohům Pelištejců. Opustili Hospodina a nesloužili mu.',
        7: 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on je vydal do ruky Pelištejců a do ruky synů Amónových.',
        8: '⌈Stírali a svírali⌉ syny Izraele od onoho roku po osmnáct let, všechny syny Izraele, kteří sídlili na druhé straně Jordánu v emorejské zemi, jež leží v Gileádu.',
        9: 'Synové Amónovi přešli Jordán, aby bojovali také proti Judovi, proti Benjamínovi a proti Efrajimovu domu. Izraelcům bylo velmi úzko.',
        10: 'Synové Izraele tehdy volali k Hospodinu o pomoc: Zhřešili jsme proti tobě, vždyť jsme opustili našeho Boha a sloužili jsme baalům.',
        11: 'Nato Hospodin synům Izraele odpověděl: Od Egypťanů, od Emorejců, od synů Amónových a od Pelištejců,',
        12: 'Sidónců, Amálekovců a Maónců, když vás utlačovali a křičeli jste ke mně, ne zachraňoval jsem vás snad z jejich ruky?',
        13: 'Jenže vy jste mě opustili a sloužili jste jiným bohům. Proto vás ⌈už nebudu⌉ zachraňovat.',
        14: 'Jděte a volejte o pomoc k bohům, které jste si vyvolili. Oni ať vás zachrání v době vašeho soužení.',
        15: 'Avšak synové Izraele řekli Hospodinu: Zhřešili jsme, nalož s námi zcela tak, jak je dobré ve tvých očích. Jen nás, prosíme, tohoto dne vysvoboď.',
        16: 'Pak odstranili ze svého středu cizí bohy, sloužili Hospodinu a jeho duše ⌈se ustrnula nad⌉ trápením Izraele.',
        17: 'Synové Amónovi byli svoláni a utábořili se v Gileádu. Synové Izraele se také shromáždili a utábořili se v Mispě.',
        18: 'Tu lidé -- gileádská knížata -- říkali jeden druhému: Muž, který začne bojovat proti synům Amónovým, se stane předákem všech obyvatel Gileádu.',
    },
    11: {
        1: 'Jiftách Gileádský byl udatný hrdina a byl synem prostitutky. Jiftácha zplodil Gileád.',
        2: 'I Gileádova žena mu porodila syny. Když synové té ženy vyrůstali, Jiftácha vyhnali. Řekli mu: Neobdržíš dědictví v domě našeho otce, protože jsi synem jiné ženy.',
        3: 'Jiftách před svými bratry utekl a bydlel v zemi Tóbu. K Jiftáchovi se seběhli ničemní muži a podnikali s ním výpady.',
        4: 'I stalo se po několika dnech, že synové Amónovi bojovali s Izraelem.',
        5: 'Pak se stalo, když už synové Amónovi bojovali s Izraelem, že přišli gileádští starší, aby vzali Jiftácha ze země Tóbu.',
        6: 'Řekli Jiftáchovi: Pojď, ⌈staneš se naším vůdcem.⌉ Bojujme proti synům Amónovým.',
        7: 'Nato Jiftách gileádským starším odpověděl: Cožpak jste mě vy neměli v nenávisti a ne vyhnali jste mě z domu mého otce? Proč jste teď, když je vám úzko, přišli za mnou?',
        8: 'Gileádští starší Jiftáchovi řekli: Proto jsme se nyní obrátili na tebe. Půjdeš s námi, budeš bojovat proti synům Amónovým a staneš se naším předákem nade všemi obyvateli Gileádu.',
        9: 'Tu Jiftách gileádským starším řekl: Jestliže mě pohnete k návratu, ⌈abych bojoval⌉ proti synům Amónovým a Hospodin je přede mnou vydá, já budu vaším velitelem.',
        10: 'Gileádští starší Jiftáchovi odpověděli: Hospodin bude mezi námi svědkem, jestliže to neprovedeme podle tvého slova.',
        11: 'Jiftách tedy šel s gileádskými staršími a lid jej ustanovil nad sebou za předáka a za vůdce. Jiftách přednesl všechna svá slova před Hospodinem v Mispě.',
        12: 'Potom poslal Jiftách posly ke králi synů Amónových se slovy: ⌈Co proti mně máš,⌉ že jsi ke mně přitáhl, abys vedl válku proti mé zemí?',
        13: 'Král synů Amónových Jiftáchovým poslům odpověděl: Vždyť Izrael zabral mou zemi, když vystupoval z Egypta, od Arnónu až po Jabok a až k Jordánu. Nuže, vrať ji zpět v pokoji.',
        14: 'Jiftách pak poslal zase znovu posly ke králi synů Amónových.',
        15: 'A řekl mu: Toto prohlásil Jiftách: Izrael nezabral moábskou zemi ani zemi synů Amónových.',
        16: 'Protože když vystupovali z Egypta, šel Izrael pustinou až k Rákosovému moři a přišel do Kádeše.',
        17: 'Tu poslal Izrael posly k edómskému králi se slovy: Dovol, ať jen projdu tvou zemí. Ale edómský král je nevyslyšel. Také k moábskému králi poslal, ale ani ten nesvolil, a tak Izrael zůstal v Kádeši.',
        18: 'Šel pustinou, obešel edómskou zemi a moábskou zemi a přišel k moábské zemi od východu slunce. Utábořili se na druhé straně Arnónu. Nevstoupili na moábské území, protože Arnón je hranicí Moábu.',
        19: 'Pak poslal Izrael posly k emorejskému králi Síchonovi, králi Chešbónu. Izrael mu řekl: Dovol, ať jen projdeme tvou zemí až na moje území.',
        20: 'Ani Síchon Izraeli nevěřil, že jen projde jeho územím. Síchon shromáždil všechen svůj lid, utábořili se v Jahasu a bojoval s Izraelem.',
        21: 'A Hospodin, Bůh Izraele, vydal Síchona a všechen jeho lid Izraeli do ruky a pobili je. Izrael obsadil celou zemi Emorejců, obyvatel oné země.',
        22: 'Obsadili veškeré emorejské území od Arnónu až k Jaboku a od pustiny až k Jordánu.',
        23: 'Nuže, Hospodin, Bůh Izraele, podrobil Emorejce svému izraelskému lidu, a ty že ho obsadíš?',
        24: 'Což neobsadíš to, co ti podrobí Kemóš, tvůj bůh, právě a jen to? Vše, co podrobil Hospodin, náš Bůh, nám, to obsadíme my.',
        25: 'Nuže, cožpak jsi opravdu lepší než moábský král Balák, syn Sipórův? Cožpak opravdu vedl při s Izraelci, bojoval snad vážně proti nim?',
        26: 'Když bydlel Izrael v Chešbónu a v jeho vesnicích, v Aróeru a v jeho vesnicích a ve všech městech, která jsou vedle Arnónu, tři sta let, proč jste je nedobyli zpět během oné doby?',
        27: 'Já jsem se vůči tobě neprohřešil, avšak ty proti mně pácháš zlo, ⌈když proti mně chceš vést⌉ válku. Ať dnes Hospodin rozhodne jako soudce mezi syny Izraele a mezi syny Amónovými.',
        28: 'Ale král synů Amónových neposlechl Jiftáchova slova, která mu vzkázal.',
        29: 'Tu na Jiftáchovi spočinul Duch Hospodinův. Táhl Gileádem a Manasesem, táhl i Mispou gileádskou a z Mispy gileádské táhl k synům Amónovým.',
        30: 'Jiftách tehdy učinil slib Hospodinu. Řekl: Jestliže opravdu vydáš syny Amónovy do mé ruky,',
        31: 'stane se toto: Cokoli vycházející, co mi vyjde naproti ze dveří mého domu, až se v pokoji navrátím od synů Amónových, bude patřit Hospodinu a přinesu to jako zápalnou oběť.',
        32: 'Potom Jiftách táhl k synům Amónovým, aby proti nim bojoval, a Hospodin je vydal do jeho ruky.',
        33: 'A pobíjel je od Aróeru, až tam, kudy se jde do Minítu, dvacet měst až po Ábel–keramím, tuze velkou porážkou. Synové Amónovi byli před syny Izraele pokořeni.',
        34: 'Když přicházel Jiftách do Mispy ke svému domu, hle, jeho dcera mu vyšla naproti s tamburínkami a s tanci. Neměl mimo ni syna ani dceru, pouze ji, jedináčka.',
        35: 'I stalo se, jak ji uviděl, že roztrhl své roucho a řekl: Běda, má dcero, nadobro jsi mě srazila. Ty ⌈na mě přivádíš zkázu.⌉ Já jsem se zavázal Hospodinu svými ústy a nemohu to vzít zpět.',
        36: 'Nato mu řekla: Můj otče, zavázal ses Hospodinu svými ústy. Nalož se mnou podle toho, co vyšlo z tvých úst, poté, co za tebe Hospodin vykonal pomstu nad tvými nepřáteli ze synů Amónových.',
        37: 'Dále svému otci řekla: Ať je se mnou uzavřena tato úmluva: Nech mi dva měsíce. Chci odejít se svými přítelkyněmi, budu se rozplývat nářkem na horách a budu oplakávat své panenství.',
        38: 'Odpověděl jí: Jdi. Dal jí na to dva měsíce a ona šla se svými přítelkyněmi a oplakávala v horách své panenství.',
        39: 'I stalo se po dvou měsících, když se navrátila k svému otci, že s ní naložil podle svého slibu, který dal. Ona nepoznala muže. Stalo se pak v Izraeli zvykem,',
        40: 'že se ⌈rok co rok⌉ dcery Izraele scházely, aby si připomínaly dceru Jiftácha Gileádského po čtyři dny v roce.',
    },
    12: {
        1: 'Efrajimští ⌈muži byli svoláni, táhli⌉ na sever a řekli Jiftáchovi: Proč jsi táhl bojovat proti synům Amónovým, a nás jsi nezavolal, abychom šli s tebou? Tvůj dům nad tebou spálíme ohněm.',
        2: 'Nato jim Jiftách řekl: Byl jsem mužem velikého sporu, já a můj lid, se syny Amónovými. Volal jsem k vám o pomoc, ale nezachránili jste mě z jejich ruky.',
        3: 'Když jsem viděl, že mě nezachráníte, ⌈vystavil jsem tedy svůj život nebezpečí,⌉ táhl jsem na syny Amónovy a Hospodin mi je vydal do ruky. Proč jste na mě tohoto dne vytáhli, abyste proti mně bojovali?',
        4: 'Pak Jiftách shromáždil všechny gileádské muže, bojoval s Efrajimem a gileádští muži pobili Efrajimce, protože řekli: Vy Gileáďané jste efrajimští uprchlíci ⌈uprostřed Efrajima a uprostřed Manasesa.⌉',
        5: 'Gileád dobyl na Efrajimovi jordánské brody. Kdykoli se stalo, že efrajimští uprchlíci říkali: Chci se přebrodit, tu jim gileádští muži odpověděli: Ty jsi Efratejec? Pokud řekl: Nejsem,',
        6: 'poručili mu: Tak řekni: Šibbolet. Pokud řekl: Sibbolet a nedokázal to vyslovit správně, chytili ho a zabili ho tam u jordánských brodů. V oné době padlo z Efrajima čtyřicet dva tisíce mužů.',
        7: 'Jiftách soudil Izrael šest let. I zemřel Jiftách Gileádský a byl pohřben v jednom z gileádských měst.',
        8: 'Po něm soudil Izrael Ibsán z Bét–lechemu.',
        9: 'Ten měl třicet synů. Třicet dcer vyvdal pryč a třicet dcer přivedl pro své syny odjinud. Izrael soudil sedm let.',
        10: 'I zemřel Ibsán a byl pohřben v Bét–lechemu.',
        11: 'Po něm soudil Izrael Elón Zabulónský. Soudil Izrael deset let.',
        12: 'I zemřel Elón Zabulónský a byl pohřben v Ajalónu v zabulónské zemi.',
        13: 'Po něm soudil Izrael Abdón, syn Hiléla Pireatónského.',
        14: 'Ten měl čtyřicet synů a třicet vnuků jezdících na sedmdesáti oslech. Soudil Izrael osm let.',
        15: 'I zemřel Abdón, syn Hiléla Pireatónského, a byl pohřben v Pireatónu v efrajimské zemi v Amáleckém pohoří.',
    },
    13: {
        1: 'Synové Izraele dále páchali to, co je v Hospodinových očích zlé, a Hospodin je vydal na čtyřicet let do ruky Pelištejců.',
        2: 'Byl jeden muž ze Soreje z danovské čeledi jménem Manóach. Jeho žena byla neplodná a nerodila.',
        3: 'Té ženě se ukázal Hospodinův anděl a řekl jí: Jen pohleď: Jsi neplodná a nerodila jsi, ale otěhotníš a porodíš syna.',
        4: 'Nuže, měj se bedlivě na pozoru: Nebudeš pít víno ani pivo a nebudeš jíst nic nečistého.',
        5: 'Neboť hle, budeš těhotná a porodíš syna. Na jeho hlavu nevstoupí břitva, protože ten chlapec bude od těhotenství Boží nazír. On začne zachraňovat Izrael z ruky Pelištejců.',
        6: 'Ta žena šla a řekla svému muži: Přišel ke mně muž Boží. Jeho vzhled byl jako vzhled Božího anděla, velmi hrozný. Nezeptala jsem se ho, odkud je, ani on mi neoznámil své jméno.',
        7: 'A řekl mi: Hle, ty budeš těhotná a porodíš syna. Teď nebudeš pít víno ani pivo a nebudeš jíst žádnou nečistotu, protože ten chlapec bude Boží nazír od samého těhotenství až do dne své smrti.',
        8: 'Nato Manóach naléhavě prosil Hospodina. Řekl: Dovol, můj Pane, prosím, ať muž Boží, kterého jsi poslal, přijde znovu k nám a poučí nás, co máme udělat s tím narozeným chlapcem.',
        9: 'A Bůh Manóacha vyslyšel. Boží anděl přišel znovu k té ženě, když pobývala na poli a její muž Manóach s ní nebyl.',
        10: 'Ta žena si tedy pospíšila, běžela a oznámila to svému muži. Řekla mu: Hle, ukázal se mi ten muž, jenž ke mně onehdy přišel.',
        11: 'Tu Manóach vstal a šel za svou ženou, přišel k tomu muži a zeptal se ho: Ty jsi ten muž, který mluvil s touto ženou? On odpověděl: To jsem já.',
        12: 'Manóach řekl: Nechť se nyní naplní tvá slova přikazující, jaké je ⌈nařízení o tom chlapci⌉ a ⌈jeho díle.⌉',
        13: 'Hospodinův anděl Manóachovi řekl: Ať se ta žena má na pozoru před vším, o čem jsem jí řekl.',
        14: 'Nepojí z ničeho, co pochází z vinné révy. Nebude pít víno ani pivo a nebude jíst žádnou nečistotu. Vše, co jsem jí přikázal, ať zachovává.',
        15: 'Manóach pak Hospodinovu andělu řekl: Dovol, ať tě zdržíme a připravíme ti kůzle.',
        16: 'Hospodinův anděl Manóachovi odpověděl: Pokud mě zdržíš, nepojím z tvého pokrmu, ale připravíš–li Hospodinu zápalnou oběť, přines ji. Manóach totiž nevěděl, že je to Hospodinův anděl.',
        17: 'Manóach se pak Hospodinova anděla zeptal: Jak zní tvé jméno? Ať tě poctíme, až se naplní tvé slovo.',
        18: 'Ale Hospodinův anděl mu odpověděl: Proč se ptáš na mé jméno? Je podivuhodné.',
        19: 'Manóach tedy vzal kůzle a přídavnou oběť a přinesl to na skálu Hospodinu. Ten ⌈se ukázal jako podivuhodný ve svém působení a Manóach a jeho žena to viděli.⌉',
        20: 'I stalo se, když stoupal plamen od oltáře k nebesům, že i Hospodinův anděl vystoupil v plameni z oltáře. Když to Manóach a jeho žena viděli, padli tváří k zemi.',
        21: 'Více se už Hospodinův anděl Manóachovi a jeho ženě neukazoval. Tehdy Manóach poznal, že to byl Hospodinův anděl.',
        22: 'Tu Manóach řekl své ženě: Jistě zemřeme, protože jsme viděli Boha.',
        23: 'Ale jeho žena mu odpověděla: Kdyby se Hospodinu zalíbilo nás usmrtit, nepřijal by z naší ruky zápalnou a přídavnou oběť, ani by nám ne ukázal všechny tyto věci a nezvěstoval by nám po celý ten čas něco takového.',
        24: 'Ta žena pak porodila syna a nazvala ho jménem Samson. Chlapec vyrůstal a Hospodin mu žehnal.',
        25: 'A Hospodinův Duch jej začal ponoukat v táboře Danovců mezi Soreou a Eštaólem.',
    },
    14: {
        1: 'Tehdy Samson sestoupil do Timny a spatřil v Timně ženu z pelištejských dcer.',
        2: 'Vystoupil tedy odtamtud a oznámil to svému otci a své matce. Řekl: Uviděl jsem v Timně ženu z pelištejských dcer. Nuže, vezměte ji pro mě za ženu.',
        3: 'Jeho otec a matka mu však řekli: Cožpak se nenajde žena mezi dcerami tvých bratrů a v celém mém lidu, že si jdeš vzít ženu z neobřezaných Pelištejců? Ale Samson svému otci odpověděl: Tu pro mě vezmi, protože ona je v mých očích ta pravá.',
        4: 'Jeho otec ani matka nevěděli, že je od Hospodina, protože on hledá u Pelištejců příležitost. V oné době Pelištejci vládli nad Izraelci.',
        5: 'I sestoupil Samson, jeho otec i matka do Timny a přišli až k vinicím u Timny a hle, potkal se s ním mladý řvoucí lev.',
        6: 'Tu jej uchvátil Duch Hospodinův a on ho roztrhl, jako by roztrhl kůzle, ačkoliv neměl nic v ruce. Svému otci ani matce nepověděl, co udělal.',
        7: 'Pak sestoupil dolů a promluvil s tou ženou; v Samsonových očích to byla ta pravá.',
        8: 'Po několika dnech se opět vrátil, aby si ji vzal. Přitom odbočil, aby se podíval na zdechlinu toho lva, a vida: V těle toho lva byl roj včel a med.',
        9: 'Tak si ho vyškrábl na dlaň a ⌈dal se při chůzi do jídla.⌉ Přišel k svému otci a matce, dal jim to a oni jedli. Nepověděl jim však, že ten med vyškrábl ze lvího těla.',
        10: 'Jeho otec pak sestoupil k té ženě a Samson tam uspořádal hostinu, protože tak to mládenci dělávali.',
        11: 'I stalo se, jak ho uviděli, že vybrali třicet společníků a ti zůstali s ním.',
        12: 'Samson jim řekl: Dovolte, ať vám dám hádanku. Jestliže mi s jistotou sdělíte ⌈její řešení⌉ za sedm dnů hostiny a uhodnete– li, dám vám třicet košil a třicet proměnných rouch.',
        13: 'Jestliže mi ho ale nebudete schopni oznámit, dáte vy mně třicet košil a třicet proměnných rouch. Řekli mu: Dej nám svou hádanku, poslechneme si ji.',
        14: 'Řekl jim tedy: Ze žrouta vyšla potrava a ze silného vyšla sladkost. Tři dny nebyli schopni oznámit řešení té hádanky.',
        15: 'Když nastal sedmý den, řekli Samsonově ženě: Přemluv svého muže, ať nám sdělí řešení té hádanky, jinak spálíme tebe i dům tvého otce ohněm. Copak jste nás svolali kvůli našemu ožebračení? ⌈ To snad ne?⌉',
        16: 'Samsonova žena se před ním rozplakala a řekla: ⌈Vůbec mě nemáš rád,⌉ nemiluješ mě. Synům mého lidu jsi dal hádanku a mně jsi nesdělil její řešení. Řekl jí: Hle, svému otci ani své matce jsem ho nesdělil, a tobě ho mám sdělit?',
        17: 'A plakala před ním těch sedm dnů, kdy měli svou hostinu. Sedmý den se stalo, že jí ho sdělil, protože na něho naléhala. I sdělila řešení té hádanky synům svého lidu.',
        18: 'Muži toho města mu pak sedmého dne, dříve než zapadlo slunko, řekli: Co je sladší než med a co silnější než lev? Odpověděl jim: Kdybyste neorali s mou jalovicí, mou hádanku byste neuhodli.',
        19: 'Tu jej uchvátil Duch Hospodinův a sestoupil do Aškalónu. Pobil z nich třicet mužů, pobral jejich výstroj a dal proměnná roucha těm, kdo sdělili řešení hádanky. Pak vzplanul jeho hněv a on vystoupil do domu svého otce.',
        20: 'Samsonova žena se potom dostala jeho příteli, který mu byl společníkem.',
    },
    15: {
        1: 'I stalo se po několika dnech ve dnech sklizně pšenice, že Samson navštívil svou ženu s kůzletem. Řekl: Chci vejít ke své ženě do pokoje. Ale její otec mu nedovolil vejít.',
        2: 'Její otec dále řekl: Říkal jsem si stále, že jsi ji opravdu neměl rád, a dal jsem ji tvému společníkovi. Což není její mladší sestra hezčí než ona? Nechť je tvá místo ní.',
        3: 'Ale Samson jim řekl: Tentokrát jsem vůči Pelištejcům nevinný, když s nimi zle naložím.',
        4: 'Tu Samson šel a polapil tři sta lišek. Vzal pochodně, obrátil ocas k ocasu a umístil jednu pochodeň doprostřed mezi ty dva ocasy.',
        5: 'Pak zapálil na pochodních oheň a vypustil je do nepožatého obilí Pelištejců. Tak zapálil vše -- od stohu přes nepožaté obilí až po vinici i olivový háj.',
        6: 'Pelištejci se ptali: Kdo tohle udělal? A lidé říkali: Samson, zeť toho Timnaťana, protože vzal jeho ženu a dal ji jeho společníkovi. A tak Pelištejci vyšli a upálili ji i jejího otce ohněm.',
        7: 'Nato jim Samson řekl: Pokud budete páchat něco takového, tak nepřestanu, dokud se vám ne pomstím.',
        8: 'A zbil je, ⌈hlava nehlava,⌉ velkou ranou. Pak sestoupil dolů a usadil se ve skalní strži Étamu.',
        9: 'Pelištejci však vytáhli, utábořili se v Judsku a rozložili se v Lechí.',
        10: 'Judští muži se ptali: Proč jste proti nám vytáhli? Odpověděli: Abychom spoutali Samsona. Vytáhli jsme, abychom mu provedli to, co on provedl nám.',
        11: 'Tři tisíce mužů z Judska tedy sestoupilo ke skalní strži Étamu a řekli Samsonovi: Cožpak jsi nevěděl, že nad námi vládnou Pelištejci? Co jsi nám to provedl? Odpověděl jim: To, co provedli mně, to jsem i já provedl jim.',
        12: 'Řekli mu: Sestoupili jsme, abychom tě spoutali, abychom tě vydali Pelištejcům do ruky. Nato jim řekl Samson: Přísahejte mi, že vy proti mně nezasáhnete.',
        13: 'Prohlásili tedy před ním: Ne, jenom tě pevně svážeme a vydáme tě do jejich ruky. Určitě tě neusmrtíme. Svázali ho do dvou nových popruhů a odvedli ho od té skály.',
        14: 'Když přicházel k Lechí, Pelištejci ⌈ho přivítali řevem.⌉ Vtom ho uchvátil Duch Hospodinův a popruhy, které měl na pažích, byly jako knoty, které se spálily v ohni, a pouta se mu uvolnila z rukou.',
        15: 'Pak našel čerstvou oslí čelist, vztáhl ruku, zmocnil se jí a pobil s ní tisíc mužů.',
        16: 'Tehdy Samson pravil: Oslí čelistí ⌈hromadu, dvě hromady,⌉ oslí čelistí pobil jsem tisíc mužů.',
        17: 'I stalo se, když domluvil, že odhodil tu čelist z ruky a nazval ono místo Rámat–lechí.',
        18: 'Pak dostal velkou žízeň a volal k Hospodinu. Řekl: Ty jsi vložil do ruky svého otroka tuto velikou spásu a teď tu zemřu žízní a padnu do ruky těch neobřezanců!',
        19: 'A Bůh rozpoltil prohlubeň, která je v Lechí. Vyšla z ní voda, on se napil, jeho duch se navrátil a ⌈ožil. Proto ji nazval⌉ jménem Pramen volajícího, jenž je v Lechí až do tohoto dne.',
        20: 'Soudil potom Izrael za dnů Pelištejců dvacet let.',
    },
    16: {
        1: 'Potom šel Samson do Gazy. Uviděl tam prostitutku a vešel k ní.',
        2: 'Obyvatelům Gazy bylo řečeno: Přišel sem Samson. Obcházeli a číhali na něho celou noc v bráně toho města a celou tu noc tiše vyčkávali se slovy: Až do svítání a pak ho zabijeme.',
        3: 'Samson však ležel jen do půlnoci. Uprostřed noci vstal, uchopil ⌈vrata městské brány a obě veřeje a vyrazil je i se závorou.⌉ Položil si je na ramena a vynesl na vrchol hory, která se tyčí směrem k Chebrónu.',
        4: 'I stalo se potom, že se zamiloval do ženy v údolí Sorék jménem Delíla.',
        5: 'Vypravili se k ní tedy pelištejští vladaři a řekli jí: Umluv ho a zjisti, v čem spočívá jeho velká síla a čím jej přemůžeme a svážeme, abychom ho pokořili. My ti dáme každý tisíc sto šekelů stříbra.',
        6: 'A tak Delíla řekla Samsonovi: Pověz mi, prosím, v čem spočívá tvá velká síla a čím můžeš být spoután, abys byl poražen.',
        7: 'Samson jí pověděl: Jestliže mě svážou sedmi syrovými lany, která nebyla vysušena, zeslábnu a budu jako kterýkoli jiný člověk.',
        8: 'Pelištejští vladaři jí tedy přinesli sedm syrových lan, která nebyla vysušena, a těmi ho svázala.',
        9: 'Ti, kdo na něj číhali, seděli u ní v pokoji. Řekla mu: Jdou na tebe Pelištejci, Samsone! Zpřetrhal ta lana, jako se přetrhne šňůrka z koudele, když se přiblíží k ohni, a jeho síla nebyla odhalena.',
        10: 'Nato Delíla Samsonovi řekla: Vida, podváděl jsi mě a vykládal jsi mi lži. Nyní mi prosím pověz, čím můžeš být spoután.',
        11: 'Řekl jí: Jestliže mě pevně svážou novými popruhy, s nimiž nebyla konána práce, zeslábnu a budu jako kterýkoli jiný člověk.',
        12: 'Delíla tedy vzala nové popruhy a svázala ho jimi. Pak mu řekla: Jdou na tebe Pelištejci, Samsone! Ti, kdo na něj číhali, seděli v pokoji. Ale on je na svých pažích zpřetrhal jako šňůry.',
        13: 'Delíla nato Samsonovi řekla: Až doposud jsi mě podváděl a vykládal jsi mi lži. Pověz mi, čím můžeš být spoután. Řekl jí: Stačí, když vetkáš sedm pramenů vlasů mé hlavy do osnovy.',
        14: 'Upevnila osnovu ještě kolíkem a řekla mu: Jdou na tebe Pelištejci, Samsone! On se probral ze spánku a vytrhl ten kolík, člunek i osnovu.',
        15: 'Nato mu řekla: Jak můžeš říkat: Miluji tě, když tvé srdce není se mnou? Takhle jsi mě třikrát podvedl a nepověděl jsi mi, v čem spočívá tvá velká síla.',
        16: 'I stalo se, když na něho naléhala svými slovy celé dny, dotírala na něho, že se jeho duše k smrti unavila.',
        17: 'Tu jí otevřel celé své srdce a řekl jí: Na mou hlavu nevstoupila břitva, protože od lůna své matky jsem Boží nazír. Pokud bych byl oholen, odstoupí ode mě má síla, zeslábnu a budu jako každý jiný člověk.',
        18: 'Když Delíla viděla, že jí otevřel celé své srdce, vzkázala a zavolala pelištejské vladaře: Tentokrát přijďte, protože mi otevřel celé své srdce. Pelištejští vladaři k ní přišli a přinesli s sebou stříbro.',
        19: 'I uspala jej na svých kolenou, pak zavolala jednoho muže a nechala oholit sedm pramenů vlasů jeho hlavy. ⌈Začala ho ponižovat⌉ a jeho síla od něj odstoupila.',
        20: 'Opět řekla: Jdou na tebe Pelištejci, Samsone! Probral se ze spánku a řekl si: Vyjdu z toho jako toli krát předtím a otřepu se. On nevěděl, že se od něj Hospodin odvrátil.',
        21: 'Pelištejci ho chytili, vyloupali mu oči, zavedli ho do Gazy a svázali ho bronzovými okovy. Byl přinucen mlít ve vězení.',
        22: 'Tam, kde byl oholen, mu ale vlasy na hlavě začaly dorůstat.',
        23: 'Pelištejští vladaři se shromáždili, aby obětovali velký obětní hod pro svého boha Dágona a pro radost. Řekli: Náš bůh nám vydal do ruky našeho nepřítele Samsona.',
        24: 'Když ho lid viděl, chválil svého boha, neboť řekl: Náš bůh nám vydal do ruky našeho nepřítele a pustošitele naší země, který rozmnožil naše pobité.',
        25: 'I stalo se, ⌈když jim bylo dobře u srdce,⌉ že řekli: Zavolejte Samsona, ať nás baví. Zavolali tedy Samsona z vězení, dováděl před nimi a postavili ho mezi sloupy.',
        26: 'Tu řekl Samson mládenci, který ho držel za ruku: Pusť mě a nech mě ohmatat ty sloupy, kterými je dům držen, ať se o ně opřu.',
        27: 'Ten dům byl plný mužů a žen, byli tam všichni pelištejští vladaři a na střeše asi tři tisíce mužů a žen, kteří se dívali, jak je Samson baví.',
        28: 'I volal Samson k Hospodinu. Řekl: Panovníku Hospodine, rozpomeň se, prosím, na mě a posilni mě, prosím, ještě tentokrát, Bože, ať se Pelištejcům pomstím jedinou pomstou za obě své oči.',
        29: 'Pak Samson pevně objal oba prostřední sloupy, kterými byl dům držený, a vzepřel se o ně, o jeden svou pravicí a o druhý svou levicí.',
        30: 'Samson řekl: Ať má duše zemře s Pelištejci. Napnul sílu a ten dům spadl na vladaře a na všechen lid, který v něm byl. Mrtvých, které usmrtil při svém skonu, bylo více, než těch, které usmrtil za svého života.',
        31: 'Potom sestoupili jeho bratři a celý dům jeho otce, vyzvedli ho, vynesli a pohřbili ho mezi Soreou a Eštaólem do hrobu jeho otce Manóacha. On soudil Izrael dvacet let.',
    },
    17: {
        1: 'Byl jeden muž z efrajimského pohoří jménem Míkajáš.',
        2: 'Ten řekl své matce: Tisíc sto šekelů stříbra, které ti bylo vzato a ty jsi kvůli němu vyslovila kletbu a také jsi mi ji řekla, hle, to stříbro je u mě. Vzal jsem ho já. Jeho matka řekla: Můj synu, ⌈jsi požehnaný Hospodinu.⌉',
        3: 'A vrátil těch tisíc sto šekelů stříbra své matce. Jeho matka řekla: To stříbro jsem cele oddělila pro Hospodina od sebe svému synovi, aby zhotovil tesanou a litou modlu. Nyní ti je vracím.',
        4: 'On to stříbro vrátil své matce. Jeho matka vzala dvě stě šekelů stříbra, dala ho zlatníkovi a ten mu zhotovil tesanou a litou modlu, která stála v Míkajášově domě.',
        5: 'Ten muž Míka měl dům bohů, zhotovil si efód a domácího bůžka. Zplnomocnil jednoho ze svých synů a ten se mu stal knězem.',
        6: 'V oněch dnech ne byl v Izraeli král; každý dělal, co bylo v jeho očích správné.',
        7: 'Byl pak jeden mládenec z judského Betléma, z Judovy čeledi. Byl to lévita pobývající tam jako cizinec.',
        8: 'Ten muž odešel z města, z judského Betléma, aby jako cizinec pobýval, kde se naskytne, a přišel do efrajimského pohoří až k Míkovu domu, ⌈jak konal svou pouť.⌉',
        9: 'Tu se ho Míka zeptal: Odkud přicházíš? Řekl mu: Jsem lévita z judského Betléma a putuji, abych jako cizinec pobýval, kde se naskytne.',
        10: 'Nato mu Míka řekl: Zůstaň se mnou a buď mi otcem a knězem. Já ti dám deset šekelů stříbra na rok, ⌈řádné ošacení⌉ a stravu. Lévita tedy šel.',
        11: 'A lévita byl ochoten u toho muže zůstat. Ten mládenec pro něho byl jako jeden z jeho synů.',
        12: 'Míka lévitu zplnomocnil, on se stal jeho kněžským služebníkem a zůstal v Míkově domě.',
        13: 'Míka tehdy řekl: Nyní jsem poznal, že mi Hospodin bude prokazovat dobro, protože se u mě stal knězem ten lévita.',
    },
    18: {
        1: 'V oněch dnech ne byl v Izraeli král. A v oněch dnech pro sebe danovský kmen hledal dědictví, aby se usídlil, protože mu až do onoho dne nepřipadlo mezi izraelskými kmeny nic do dědictví.',
        2: 'Synové Danovi tedy poslali pět mužů ze své čeledi, bojovníků ze svých končin ze Soreje a z Eštaólu, aby prozkoumali zemi a aby ji důkladně prohlédli. Řekli jim: Jděte a důkladně prohlédněte tu zemi. Přišli do efrajimského pohoří až k Míkovu domu a nocovali tam.',
        3: 'Když byli u Míkova domu, všimli si hlasu toho lévijského mládence. Zašli tam a zeptali se ho: Kdo tě sem přivedl? Co tady děláš? Co to tu máš?',
        4: 'Odpověděl jim: To a to se mnou Míka dojednal, najal mě a já jsem se mu stal knězem.',
        5: 'Nato mu řekli: Prosíme, doptávej se Boha, ať poznáme, zdali dopřeje úspěch naší cestě, po níž jdeme.',
        6: 'Kněz jim řekl: Jděte v pokoji. Vaše cesta, po níž půjdete, je před Hospodinem.',
        7: 'Těch pět mužů šlo, přišli do Lajiše a viděli lid, který v něm byl poklidný, bydlel v bezpečí po způsobu Sidónců a byl bezstarostný. Nikdo v zemi nepotupoval úmluvu, ne získával vlastnictví mocí. Byli daleko od Sidónců a neměli s nikým úmluvu.',
        8: 'Vrátili se ke svým bratrům do Soreje a Eštaólu. Jejich bratři se jich zeptali: ⌈Jak jste na tom?⌉',
        9: 'Odpověděli: Vstaňte a vytáhneme proti nim, protože jsme viděli tu zemi a hle, je velmi dobrá, ale vy jste neteční. Nebuďte líní jít, vstoupit do té země a obsadit ji.',
        10: 'Až vytáhnete, přijdete k bezstarostnému lidu a země je rozlehlá na všechny strany, vždyť Bůh ji vydal do vaší ruky -- místo, kde není nouze vůbec v ničem, co bývá na zemi.',
        11: 'I vyrazilo odtamtud z danovské čeledi, ze Soreje a z Eštaólu, šest set mužů, přepásaných válečnými zbraněmi.',
        12: 'Vytáhli a utábořili se u Kirjat–jearímu v Judsku. Kvůli tomu nazvali ono místo Danovský tábor a je tomu tak až do tohoto dne. Všimněte si ho za Kirjat–jearímem.',
        13: 'Odtamtud prošli efrajimským pohořím a přišli až k Míkovu domu.',
        14: 'Tu promluvilo těch pět mužů, kteří se vydali prozkoumat zemi Lajiš. Řekli svým bratrům: Zdalipak víte, že je v těchto domech efód, domácí bůžek a tesaná a litá modla? Nuže, rozvažte, co provedete.',
        15: 'Zašli tam tedy, přišli k domu toho lévijského mládence, k domu Míkovu, a ⌈zeptali se ho, jak se mu daří,⌉',
        16: 'zatímco šest set mužů z Danových synů, přepásaných válečnými zbraněmi, stálo u vchodu do brány.',
        17: 'Pak vystoupilo těch pět mužů, kteří se vydali prozkoumat zemi. Přišli tam, vzali tu tesanou modlu a efód, domácího bůžka i litou modlu. Kněz přitom stál u vchodu do brány se šesti sty muži, přepásanými válečnými zbraněmi.',
        18: 'Když ti muži vešli do Míkova domu a vzali tesanou modlu, efód, domácího bůžka a litou modlu, zeptal se jich kněz: Co to děláte?',
        19: 'Odpověděli mu: Mlč, polož si ruku na ústa a pojď s námi. Buď nám otcem a knězem. Co je lepší: Abys byl knězem domu jednoho muže, nebo abys byl knězem kmene a čeledi v Izraeli?',
        20: 'To se srdci toho kněze líbilo. Vzal efód, domácího bůžka a tesanou modlu a vstoupil mezi lid.',
        21: 'Nato se obrátili a vyšli. Malé děti, dobytek a cenný majetek umístili před sebe.',
        22: 'Vzdálili se od Míkova domu a tu se shromáždili muži z domů, které stály u domu Míkova, a stíhali syny Danovy.',
        23: 'Křičeli na syny Danovy. Ti se ohlédli a řekli Míkovi: Jaké máš přání, že ses shromáždil?',
        24: 'Odpověděl jim: Vzali jste mé bohy, které jsem zhotovil, a kněze a odešli jste. Co se mnou bude dál? Jak se mě můžete ptát: Jaké máš přání?',
        25: 'Nato mu synové Danovi řekli: Nezvyšuj na nás hlas, jinak se na vás vrhnou rozhořčení muži a ztratíš život svůj i život svého domu.',
        26: 'Synové Danovi pak šli svou cestou. Když Míka viděl, že jsou silnější než on, obrátil se a vrátil se domů.',
        27: 'Oni vzali s sebou to, co si Míka zhotovil, a kněze, kterého měl, a přitáhli k Lajiši na poklidný a bezstarostný lid. Pobili je ostřím meče a město spálili ohněm.',
        28: 'A nebyl, kdo by město vysvobodil, protože bylo daleko od Sidónu a neměli s nikým úmluvu. Bylo v údolí u Bét–rechóbu. Synové Danovi to město opět postavili a usadili se v něm.',
        29: 'Tehdy nazvali to město jménem Dan podle jména svého otce Dana, který se narodil Izraelovi. Původně však mělo to město jméno Lajiš.',
        30: 'Synové Danovi tam tu tesanou modlu postavili pro sebe a Jónatan, syn Geršóma, syna Mojžíšova, on i jeho synové se stali kněžími pro danovský kmen až do dne vystěhování té země.',
        31: 'Míkovu tesanou modlu, kterou zhotovil, tam měli pro sebe umístěnou po všechny dny, kdy byl dům Boží v Šílu.',
    },
    19: {
        1: 'I stalo se ⌈v oněch dnech, kdy ne byl v Izraeli král,⌉ že nějaký lévita pobývající jako cizinec v odlehlých končinách efrajimského pohoří si vzal konkubínu z judského Betléma.',
        2: 'Jeho konkubína ⌈mu byla nevěrná,⌉ odešla od něj do domu svého otce do judského Betléma a zůstala tam po dobu čtyř měsíců.',
        3: 'Tu její muž vstal a šel za ní, promluvit k jejímu srdci, aby se navrátila. Byl s ním jeho služebník a oslí spřežení. I uvedla jej do domu svého otce. Když ho otec té dívky spatřil, zaradoval se, že se s ním setkává.',
        4: 'Jeho tchán, otec dívky, ho přemluvil, a tak s ním tři dny pobyl. Jedli, pili a nocovali tam.',
        5: 'I stalo se čtvrtého dne, když časně ráno vstali a povstal k odchodu, že otec dívky řekl svému zeťovi: Posilni se kouskem chleba a potom půjdete.',
        6: 'Zůstali tedy, ti dva spolu jedli a pili a otec dívky tomu muži řekl: Prosím, buď tak laskav a přenocuj, ⌈ať je ti dobře u srdce.⌉',
        7: 'Ten muž vstal k odchodu, ale jeho tchán ho přinutil, a tak se vrátil a znovu tam přenocoval.',
        8: 'Pátý den vstal k odchodu časně zrána. Otec té dívky řekl: Posilni se přece a zdržte se, než den pokročí. A oba pojedli.',
        9: 'Když vstal ten muž k odchodu, on i jeho konkubína a jeho služebník, tu mu řekl jeho tchán, otec dívky: Podívej se přece, den se nachýlil ⌈a nastává večer.⌉ Ano, zůstaňte přece přes noc, dnes si lehněte. Přenocuj tady, ⌈ať je ti dobře u srdce⌉ a zítra časně vstanete na svou cestu a odejdeš ke svému stanu.',
        10: 'Muž ale nechtěl přenocovat. Vstal, vyšel a přišel až naproti Jebúsu, což je Jeruzalém, a s ním osedlané oslí spřežení a jeho konkubína.',
        11: 'Byli u Jebúsu a den velmi pokročil. Tu řekl služebník svému pánu: Pojďme prosím, zajděme do tohoto jebúsejského města a přenocujme v něm.',
        12: 'Jeho pán mu odpověděl: Nezajdeme do města cizozemců, kteří nejsou ze synů Izraele. Projdeme až do Gibeje.',
        13: 'A řekl svému služebníku: Pojď, přiblížíme se k jednomu z těch míst. Přenocujeme v Gibeji nebo v Rámě.',
        14: 'Prošli tedy tím místem, šli a slunce jim zapadlo u Gibeje, která patří Benjamínovi.',
        15: 'A odbočili tam, aby došli do Gibeje a přenocovali. Přišel a posadil se na náměstí toho města, ale nebyl nikdo, kdo by je přijal do domu, aby mohli přenocovat.',
        16: 'Vtom hle, nějaký stařec přichází večer z pole od svého díla. Ten muž byl z efrajimského pohoří a jako cizinec pobýval v Gibeji. Muži toho místa byli ovšem synové Ben jamínovi.',
        17: 'Když pozvedl své oči a spatřil toho muže, poutníka, na náměstí města, zeptal se ten starý muž: Kam jdeš a odkud přicházíš?',
        18: 'Odpověděl mu: Procházíme z judského Betléma až do odlehlých končin efrajimského pohoří, odkud pocházím. Šel jsem do judského Betléma, jsem poutník, a teď jdu do Hospodinova domu. Není však, kdo by mě přijal do domu.',
        19: 'Mám i slámu a krmivo pro naše osly a také chléb a víno mám pro sebe i pro tvou služebnici a pro služebníka, kterého mají tví otroci s sebou. Vůbec v ničem nemám nouzi.',
        20: 'Nato řekl ten stařec: Pokoj tobě. Jen uval všechnu svou nouzi na mě. Jenom nezůstávej přes noc na náměstí.',
        21: 'Přivedl ho do svého domu, namíchal krmení pro osly a umyli si nohy. Pak jedli a pili.',
        22: 'Když se posilňovali, hle, muži toho města, ničemníci, obklíčili dům, tloukli na dveře a volali na starce, vlastníka domu: Vyveď toho muže, který přišel do tvého domu, ať ho poznáme.',
        23: 'Vlastník domu k nim vyšel a řekl jim: Ne, bratři moji, nepáchejte přece zlo poté, co tento muž přišel do mého domu. Nedopouštějte se takového bláznovství.',
        24: 'Zde je má dcera, panna, a jeho konkubína. Ihned je vyvedu. Ponižte je a udělejte s nimi, co je vám libo, ale proti tomuto muži se nedopouštějte žádného takového bláznovství.',
        25: 'Ti muži ho však nechtěli poslechnout. Tu se ten muž chopil své konkubíny a vyvedl ji k nim na ulici. Poznali ji a vyžívali se na ní celou noc až do rána a propustili ji ⌈při východu⌉ jitřenky.',
        26: 'Ráno ta žena přišla nazpět a zhroutila se u vchodu do domu toho muže, kde byl její pán. Ležela tam až do svítání.',
        27: 'Její pán ráno vstal, otevřel dveře domu a vyšel, aby se vydal na cestu, a hle, žena, jeho konkubína, leží u vchodu do domu a její ruce jsou na prahu.',
        28: 'Řekl jí: Vstaň a půjdeme, ale ona neodpovídala. Vzal ji tedy na osla. I vstal ten muž a vydal se k domovu.',
        29: 'Když přišel do svého domu, vzal nůž, uchopil konkubínu, rozsekal ji podle jejích kostí na dvanáct dílů a rozeslal ji po celém území Izraele.',
        30: 'Ať každý, kdo to vidí, řekne: Nestalo se ani nebylo viděno něco takového ode dne, kdy vyšli synové Izraele z egyptské země, až do tohoto dne. ⌈Zvažte to,⌉ poraďte se a vyslovte se.',
    },
    20: {
        1: 'Tehdy přišli všichni synové Izraele a obec se shromáždila jako jeden muž od Danu až po Beer–šebu i zemi Gileád k Hospodinu do Mispy.',
        2: 'Vůdcové všeho lidu ze všech izraelských kmenů se postavili ve shromáždění Božího lidu, čtyři sta tisíc mužů, pěšáků schopných tasit meč.',
        3: 'Synové Benjamínovi slyšeli, že synové Izraele vytáhli do Mispy. Synové Izraele se ptali: Povězte, jak se stalo takové zlo?',
        4: 'Nato odpověděl lévita, muž té zavražděné ženy. Řekl: Já jsem se svou konkubínou přišel přenocovat do Gibeje, která patří Benjamínovi.',
        5: 'Občané Gibeje však proti mně povstali a obklíčili kvůli mně v noci dům. Mě zamýšleli zabít a mou konkubínu ponižovali, až zemřela.',
        6: 'Tu jsem svou konkubínu uchopil, rozsekal jsem ji na kusy a poslal jsem ji na celé území izraelského dědictví, protože oni spáchali v Izraeli hanebnost a bláznovství.',
        7: 'Hle, vy všichni jste synové Izraele; ujměte se tady té záležitosti a učiňte rozhodnutí.',
        8: 'Tehdy všechen lid povstal jako jeden muž se slovy: Nikdo nepůjdeme ke svému stanu a nikdo neodejdeme do svého domu.',
        9: 'Nuže, toto je věc, kterou provedeme s Gibejí: Potáhneme proti ní podle losu.',
        10: 'Vezmeme tedy deset mužů ze sta od každého z izraelských kmenů a sto z tisíce a tisíc z desetitisíce, aby vzali zásobu potravin pro lid, který přitáhne na Benjamínovu Gebu, aby s ní naložil podle všeho bláznovství, které spáchala v Izraeli.',
        11: 'Tak ⌈se odebrali všichni izraelští muži⌉ k tomu městu jako jeden muž -- spojenci.',
        12: 'Dále poslaly izraelské kmeny muže do všech Benjamínových kmenů se slovy: ⌈Jaké zlo se to u vás stalo?⌉',
        13: 'Nyní tedy vydejte ty ničemníky, kteří jsou v Gibeji. Usmrťme je a vyhlaďme zlo z Izraele. Ale synové Benjamínovi nechtěli uposlechnout své bratry, syny Izraele.',
        14: 'Pak se synové Benjamínovi shromáždili z měst do Gibeje, aby vytáhli do boje se syny Izraele.',
        15: 'V onen den bylo napočítáno synů Benjamínových z měst dvacet šest tisíc mužů schopných tasit meč, mimo sedmi set vybraných mužů, kteří byli napočítáni z obyvatel Gibeje.',
        16: 'Ze všeho tohoto lidu bylo vybráno sedm set mužů ⌈nevládnoucích pravou rukou;⌉ každý z nich vrhal z praku kámen nachlup přesně a neminul cíl.',
        17: 'Izraelských mužů bylo napočítáno mimo Benjamínců čtyři sta tisíc mužů schopných tasit meč; všichni to byli bojovníci.',
        18: 'Povstali, vystoupili do Bét–elu a doptávali se Boha. Synové Izraele se ptali: Kdo z nás má vytáhnout jako první do bitvy se syny Benjamínovými? Hospodin odpověděl: Juda půjde jako první.',
        19: 'Ráno tedy synové Izraele povstali a utábořili se u Gibeje.',
        20: 'Pak ⌈vytáhli izraelští muži⌉ do bitvy s Benjamínci. Izraelští muži se proti nim sešikovali k bitvě u Gibeje.',
        21: 'Vtom vytáhli synové Benjamínovi z Gibeje a srazili v Izraeli v onen den dvacet dva tisíc mužů k zemi.',
        22: 'Ale lid, izraelští muži, se posilnili a znovu se sešikovali k boji na místě, kde se sešikovali prvního dne.',
        23: 'Tehdy synové Izraele přišli a plakali před Hospodinem až do večera a doptávali se Hospodina: To se máme znovu pustit do boje se syny svého bratra Benjamína? Hospodin řekl: Vytáhněte proti němu.',
        24: 'Synové Izraele se tedy druhého dne přiblížili k synům Benjamínovým.',
        25: 'I druhého dne jim Benjamín vytáhl naproti z Gibeje a srazil mezi syny Izraele znovu k zemi osmnáct tisíc mužů. Ti všichni byli ozbrojeni mečem.',
        26: 'Tu vystoupili všichni synové Izraele a všechen lid, přišli do Bét–elu, plakali a pobývali tam před Hospodinem. V onen den se postili až do večera a přinesli před Hospodina zápalné a pohostinné oběti.',
        27: 'Pak se synové Izraele doptávali Hospodina; v oněch dnech tam byla truhla Boží smlouvy.',
        28: 'A Pinchas, syn Eleazara, syna Áronova, před ní v oněch dnech stál se slovy: To máme stále znovu táhnout do boje se syny svého bratra Benjamína, nebo máme přestat? Hospodin řekl: Vytáhněte, protože zítra ho vydám do tvé ruky.',
        29: 'Izrael pak umístil v okolí Gibeje zálohy.',
        30: 'Třetího dne vytáhli synové Izraele proti synům Benjamínovým a sešikovali se u Gibeje jako dvakrát předtím.',
        31: 'I synové Benjamínovi vytáhli naproti tomu lidu, odlákáni od města, a začali pobíjet některé z toho lidu, probodávat je jako již dvakrát předtím. Na silnicích, z nichž jedna vystupuje do Bét–elu a druhá do Gibeje, zůstalo v poli asi třicet mužů z Izraele.',
        32: 'Tu synové Benjamínovi řekli: Jsou před námi poraženi jako předtím. Synové Izraele však řekli: Utíkejme, odlákáme je od města k silnicím.',
        33: 'A všichni izraelští muži vstali ze svého místa a sešikovali se v Baal–támaře, zatímco se izraelská záloha vyřítila ze svého místa z Gebské planiny.',
        34: 'Odnaproti přitáhlo ke Gibeji deset tisíc mužů vybraných z celého Izraele. Rozpoutala se těžká bitva a oni nevěděli, že je zasáhla zhouba.',
        35: 'I porazil Hospodin Benjamína před Izraelem. Synové Izraele v onen den uvrhli do zkázy dvacet pět tisíc a sto mužů z Benjamína. Ti všichni byli ozbrojeni mečem.',
        36: 'Synové Benjamínovi viděli, že jsou poraženi. Izraelští muži přenechali Benjamínovi území, protože spoléhali na zálohu, kterou umístili proti Gibeji.',
        37: 'Tu ti ze zálohy přispěchali a vtrhli do Gibeje. Záloha vytáhla a pobila celé město ostřím meče.',
        38: 'Izraelští muži měli se zálohou určené znamení: Nechte z města vystupovat mnoho kouře, abyste jim dali znamení.',
        39: 'Izraelští muži se v boji obrátili a Benjamínci začali pobíjet probodené z izraelských mužů, asi třicet mužů, protože si řekli: Jistě je před námi nadobro poražen jako v té první bitvě.',
        40: 'Tehdy začalo vystupovat z města znamení -- sloup kouře. Benjamín se za ním ohlédl a hle, celé to město stoupalo v plamenech k nebesům.',
        41: 'Tu se ⌈izraelští muži obrátili a muži Benjamínovi se vyděsili,⌉ protože zjistili, že je zasáhla zhouba.',
        42: 'Obrátili se před izraelskými muži směrem do pustiny, ale válečná vřava jim byla v patách a ti, kteří vyšli z měst, je sráželi v jejich středu.',
        43: 'Obklíčili Benjamína, pronásledovali ho bez odpočinutí, šlapali mu na paty až před Gibeu na východu slunce.',
        44: 'Tak padlo z Benjamína osmnáct tisíc mužů. Byli to samí bojovníci.',
        45: 'Ostatní se obrátili a utíkali do pustiny ke skále Rimónu. Dohledali z nich na silnicích pět tisíc mužů, ⌈stíhali je⌉ až ke Gideómu a pobili z nich dva tisíce mužů.',
        46: 'Všech padlých z Benjamína bylo v onen den dvacet pět tisíc mužů schopných tasit meč. Byli to samí bojovníci.',
        47: 'Šest set mužů se však obrátilo a utíkali do pustiny ke skále Rimónu. Pobývali ve skále Rimónu čtyři měsíce.',
        48: 'Izraelští muži se pak vrátili k synům Benjamínovým a pobili je ostřím meče, muže z města, stejně jako zvíře, stejně jako všechno, co se našlo. Také všechna města, ⌈která objevili,⌉ podpálili.',
    },
    21: {
        1: 'A všichni izraelští muži v Mispě přísahali: Nikdo z nás nedá Benjamínci za ženu svou dceru.',
        2: 'Potom lid přišel do Bét–elu, seděli tam až do večera před Bohem, ⌈pozvedli svůj hlas a dali se do velkého pláče.⌉',
        3: 'A ptali se: Hospodine, Bože Izraele, proč se tohle stalo v Izraeli, aby byl dnes od Izraele odečten jeden kmen?',
        4: 'I stalo se příštího dne, že lid časně ráno vstal, postavili tam oltář a přinesli zápalné a pohostinné oběti.',
        5: 'Synové Izraele se pak zeptali: Kdo ze všech izraelských kmenů nevystoupil k Hospodinu do shromáždění? Protože byla vydána veliká přísaha proti tomu, kdo by nevystoupil k Hospodinu do Mispy: Jistě bude usmrcen.',
        6: 'Synové Izraele totiž litovali svého bratra Benjamína a říkali: Dnes byl od Izraele odseknut jeden kmen.',
        7: 'Co pro ně uděláme, pro ty zbývající Benjamínce, aby měli ženy? My jsme přece přísahali při Hospodinu, že jim nedáme za ženy žádné z našich dcer.',
        8: 'A ptali se: Kdo jako jediný z izraelských kmenů nevystoupil k Hospodinu do Mispy? A hle, z Jábeše v Gileádu nepřišel do tábora na shromáždění nikdo.',
        9: 'Byl tedy spočítán lid a vida: Nikdo z obyvatel Jábeše v Gileádu tam nebyl.',
        10: 'A tak tam poslali z obce dvanáct tisíc mužů z bojovníků a přikázali jim: Jděte, pobijete obyvatele Jábeše v Gileádu ostřím meče, rovněž ženy a malé děti.',
        11: 'Toto je věc, kterou učiníte každému muži a každé ženě, která poznala ulehnutí s mužem -- zasvětíte je zkáze.',
        12: 'I nalezli mezi obyvateli Jábeše v Gileádu čtyři sta dívek, panen, které nepoznaly muže při ulehnutí s mužem, a přivedli je do tábora v Šílu, které je v kenaanské zemi.',
        13: 'Celá obec pak vzkázala a promluvila k synům Benjamínovým, kteří byli ve skále Rimónu. Vyhlásili jim pokoj.',
        14: 'V onen čas se tedy Benjamínci vrátili. Dali jim ženy, které zachovali při životě mezi ženami z gileádského Jábeše, ale tolik jich pro ně nenašli.',
        15: 'Lid Benjamína litoval, protože Hospodin způsobil mezi izraelskými kmeny trhlinu.',
        16: 'Nato se starší obce zeptali: Jak to uděláme se ženami pro ty zbývající, když byly ženy z Benjamína vyhubeny?',
        17: 'Řekli tedy: Benjamínovi náleží vlastnictví uprchlíka. Kmen nebude z Izraele vymazán.',
        18: 'My jim však nemůžeme dát ženy ze svých dcer, neboť synové Izraele přísahali: Proklet buď ten, kdo dá ženu Benjamínci.',
        19: 'Pak řekli: Hle, ⌈rok co rok⌉ se koná Hospodinův svátek v Šílu, které je severně od Bét–elu, na východ slunce od silnice, která vystupuje z Bét–elu do Šekemu, a na jih od Lebóny.',
        20: 'A synům Benjamínovým přikázali: Jděte, budete číhat ve vinicích.',
        21: 'Budete se dívat a hle, až vyjdou šíloské dcery plesat v tancích, vyrazíte z vinic a chytíte si každý svou ženu ze šíloských dcer. Pak odejdete do benjamínské země.',
        22: 'A stane– li se, že přijdou jejich otcové nebo bratři, aby s námi vedli spor, řekneme jim: Slitujte se nad námi kvůli nim, vždyť jsme nevzali pro každého ženu v boji. Protože vy jste jim je v pravý čas nedali, proviníte se.',
        23: 'Synové Benjamínovi tak učinili a unesli ženy podle svého počtu z tanečnic, které uchvátili. Potom odešli a navrátili se ke svému dědictví. Postavili města a usadili se v nich.',
        24: 'A tak se v onen čas odtamtud synové Izraele rozešli, každý ke svému kmeni a ke své čeledi. Odešli odtamtud každý ke svému dědictví.',
        25: '⌈V oněch dnech ne byl v Izraeli král; každý dělal, co bylo v jeho očích správné.⌉',
    },
}
